FONTS_CACHE = []

def init_fonts_cache():
    try:
        font_files = ["font1.ttf", "font2.ttf", "font3.ttf", "font4.ttf"]
        for ff in font_files:
            if os.path.exists(ff):
                FONTS_CACHE.append(ImageFont.truetype(ff, 40))
        if not FONTS_CACHE:
            FONTS_CACHE.append(ImageFont.load_default())
    except Exception:
        FONTS_CACHE.append(ImageFont.load_default())

init_fonts_cache()

class MultiLangMiddleware(BaseMiddleware):
    """
    Определяет языковой поток пользователя (ru/en/jp).
    Использует кэш внутри board_data для автоматической очистки.
    """
    async def __call__(self, handler, event, data):
        stream = 'ru'
        if ENABLE_MULTILANG:
            user = data.get('event_from_user')
            if user:
                board_id = data.get('board_id', 'b')
                b_data = board_data[board_id]
                user_streams = b_data.setdefault('user_streams', {})
                
                stream = user_streams.get(user.id)
                if not stream:
                    stream = await get_user_stream(user.id, board_id)
                    user_streams[user.id] = stream
                    
        data['stream'] = stream
        return await handler(event, data)
class DeduplicationMiddleware(BaseMiddleware):
    def __init__(self):
        self.cache = {}
        self.cleanup_timer = time.time()
    async def __call__(self, handler, event, data):
        if not isinstance(event, types.Message):
            return await handler(event, data)
        current_time = time.time()
        if len(self.cache) > 2000 or current_time - self.cleanup_timer > 300:
            self.cache = {k: v for k, v in self.cache.items() if current_time - v < 60}
            self.cleanup_timer = current_time
        unique_key = (event.chat.id, event.message_id, event.media_group_id or 0)
        if unique_key in self.cache:
            return 
        self.cache[unique_key] = current_time
        return await handler(event, data)

NEW_USER_JOIN_HISTORY = deque(maxlen=20)
RECENT_JOINERS_CACHE = {}
RAID_LOCKDOWN_UNTIL = 0
RAID_LOCKDOWN_THRESHOLD = 3
RAID_LOCKDOWN_WINDOW = 60
RAID_LOCKDOWN_DURATION = 300

class BoardMiddleware(BaseMiddleware):
    """
    1. Определяет board_id.
    2. Реализует "Глухой Бан" (Hard Ban).
    3. Реализует автоматическую защиту от рейдов (Lockdown).
    """
    async def __call__(
        self,
        handler: Callable[[TelegramObject, Dict[str, Any]], Awaitable[Any]],
        event: TelegramObject,
        data: Dict[str, Any]
    ) -> Any:
        global RAID_LOCKDOWN_UNTIL
        
        board_id = get_board_id(event)
        data['board_id'] = board_id
        if board_id:
            user = data.get('event_from_user')
            if user:
                uid = user.id
                b_data = board_data.get(board_id)
                if b_data:
                    is_user_admin = is_admin(uid, board_id)
                    if uid in b_data['users']['banned'] and not is_user_admin:
                        try:
                            if isinstance(event, types.Message):
                                await event.delete()
                            elif isinstance(event, types.CallbackQuery):
                                pass 
                        except Exception: 
                            pass
                        return 
                        
                    # Анти-рейд
                    if not is_user_admin:
                        now = time.time()
                        is_new_user = uid not in b_data['users']['active']
                        is_recent_joiner = False
                        
                        if uid in RECENT_JOINERS_CACHE:
                            if now - RECENT_JOINERS_CACHE[uid] <= 3600:
                                is_recent_joiner = True
                            else:
                                del RECENT_JOINERS_CACHE[uid]

                        if is_new_user or is_recent_joiner:
                            # Проверяем как ручной локдаун (от админа), так и автоматический
                            if b_data.get('lockdown', False) or now < RAID_LOCKDOWN_UNTIL:
                                try:
                                    if isinstance(event, types.Message):
                                        await event.delete()
                                except Exception as e:
                                    logging.warning(f"Failed to delete event during raid lockdown: {e}")
                                return
                            
                            # Регистрируем первого захода нового юзера
                            if is_new_user and uid not in RECENT_JOINERS_CACHE:
                                # Очистка старых записей из кэша
                                if len(RECENT_JOINERS_CACHE) > 2000:
                                    cutoff = now - 3600
                                    expired = [k for k, v in RECENT_JOINERS_CACHE.items() if v < cutoff]
                                    for k in expired:
                                        del RECENT_JOINERS_CACHE[k]

                                RECENT_JOINERS_CACHE[uid] = now
                                NEW_USER_JOIN_HISTORY.append(now)
                                recent_joins = sum(1 for t in NEW_USER_JOIN_HISTORY if now - t <= RAID_LOCKDOWN_WINDOW)
                                if recent_joins > RAID_LOCKDOWN_THRESHOLD:
                                    RAID_LOCKDOWN_UNTIL = now + RAID_LOCKDOWN_DURATION
                                    print(f"🚨🚨🚨 РЕЙД ДЕТЕКТ! Активирован локдаун новых пользователей на {RAID_LOCKDOWN_DURATION} секунд! (зашло {recent_joins} за {RAID_LOCKDOWN_WINDOW}с) 🚨🚨🚨")
                                    try:
                                        if isinstance(event, types.Message):
                                            await event.delete()
                                    except Exception as e:
                                        logging.warning(f"Failed to delete event during raid lockdown: {e}")
                                    return

        return await handler(event, data)
