def get_current_item_price(item_key: str) -> int:
    from shared_state import market_state
    base = BASE_SHOP_PRICES.get(item_key, 100)
    mult = market_state.get('multipliers', {}).get(item_key, 1.0)
    return max(10, int(base * mult))

