@dp.callback_query(F.data.startswith("wd_method_"), WithdrawalStates.choosing_method)
async def cb_select_method(callback: types.CallbackQuery, state: FSMContext):
    parts = callback.data.split("_")
    if len(parts) < 3:
        await callback.answer("Ошибка в callback данных", show_alert=True)
        return
    method = parts[2] # sber, usdt, etc.
    await state.update_data(wd_method=method)
    
    method_names = {
        'sber': 'номер карты Сбербанк и Имя получателя', 
        'tinkoff': 'номер карты Тинькофф и Имя получателя', 
        'sbp': 'номер телефона и Имя получателя', 
        'vtb': 'номер карты ВТБ и Имя получателя',
        'usdt': 'адрес кошелька TRC20', 
        'btc': 'адрес BTC', 
        'eth': 'адрес ETH', 
        'sol': 'адрес SOL', 
        'xmr': 'адрес XMR'
    }
    
    req_name = method_names.get(method, 'реквизиты')
    
    req_text = f"✍️ Введите <b>{req_name}</b> для вывода:"
    await _render_shop_subview(callback, req_text, None, category="wallet")




def _get_tgach_rates_content():
    res = ["📈 <b>ПРАЙС-ЛИСТ И КУРСЫ TGACH PAY / EXCHANGE</b>\n"]
    res.append("💰 <b>Доходы:</b> Реферал <code>+1488₪</code> | Тред <code>+150₪</code> | Смена <code>+15–160₪</code> | Daily <code>+75–145₪</code> | Реакция <code>+8.5₪</code>\n")
    res.append("🛒 <b>Магазин:</b> Говно/Аминазин <code>100₪</code> | Заточка/VIP <code>400₪</code> | Мут-Ган/Щит <code>600–800₪</code> | Фольга/Понос <code>800₪</code> | Дворник/Шиза <code>1000₪</code> | Пасскод <code>1488₪</code> | Пативэн <code>2000₪</code>\n")
    res.append("💎 <b>Курс крипты (за 100 ₪):</b>")
    for code, rate in list(FAKE_CRYPTO_RATES.items())[:4]:
        crypto_val = 100 / rate
        res.append(f"• <b>{code.upper()}</b>: <code>{crypto_val:.6f}</code>")
    res.append("\n<i>* 1 Шекель (₪) = 1 RUB. Синхронизировано с Привозом и Binance.</i>")

    kb = InlineKeyboardMarkup(inline_keyboard=[
        [
            InlineKeyboardButton(text="🛒 В Магазин", callback_data="prof_shop"),
            InlineKeyboardButton(text="🔨 На Работу", callback_data="economy_work"),
        ],
        [
            InlineKeyboardButton(text="🎰 Казино Тгача", callback_data="cas:hub"),
            InlineKeyboardButton(text="💸 Дроп шекелей", callback_data="cas:menu:drop"),
        ],
        [
            InlineKeyboardButton(text="💳 Кошелек", callback_data="prof_wallet"),
            InlineKeyboardButton(text="🎲 Кости", callback_data="economy_dice"),
        ]
    ])
    return "\n".join(res), kb

@dp.message(Command("rates", "kurs", "prices", "price", "exchange", "курсы", "курс", "прайс", "цены", "прайслист", "котировки"))
async def cmd_rates(message: types.Message, board_id: str | None = None, stream: str = 'ru'):
    text, kb = _get_tgach_rates_content()
    from banner_manager import send_banner_message
    await send_banner_message(
        bot=message.bot,
        chat_id=message.chat.id,
        caption=text,
        reply_markup=kb,
        category="wallet",
        parse_mode="HTML"
    )
    try: await message.delete()
    except Exception: pass

