@dp.callback_query(F.data.startswith("dice_bet_"))
async def cb_dice_bet_quick(callback: types.CallbackQuery, board_id: str | None):
    if not board_id: return
    user_id = callback.from_user.id
    raw_bet = callback.data.replace("dice_bet_", "")
    db = await get_pool()
    result = random.randint(1, 100)
    new_bal = 0

    err_text = None
    outcome_text = ""
    bet = 0
    async with db_lock:
        async with db.execute("SELECT SUM(balance) FROM Users WHERE user_id = ?", (user_id,)) as c:
            row = await c.fetchone()
            balance = row[0] if row and row[0] is not None else 0

        if raw_bet == "all":
            bet = int(balance)
        elif raw_bet.isdigit():
            bet = int(raw_bet)
        else:
            bet = 0

        if bet < 10:
            err_text = "❌ Минимальная ставка: 10 ₪ (Недостаточно средств)"
        elif bet > balance:
            err_text = f"❌ Не хватает шекелей! Баланс: {int(balance)} ₪"
        elif bet > 10000:
            err_text = "❌ Максимальная ставка: 10 000 ₪"
        else:
            # Anti-script Cooldown
            is_ok, rem = casino_engine.check_casino_cooldown(user_id)
            if not is_ok:
                err_text = f"⏳ <b>Кости остывают!</b> Подожди <code>{rem}с</code> перед броском."
            else:
                # VIP Table Rake
                rake, active_bet = casino_engine.calculate_vip_table_rake(bet)
                if rake > 0:
                    await add_to_abu_fund(db, rake)

                # Raid Chance
                is_raid, raid_notice = check_casino_raid_trigger(balance=int(balance), bet=bet)
                if is_raid and raid_notice:
                    await deduct_user_global_balance(db, user_id, board_id, bet)
                    await add_to_abu_fund(db, bet)
                    await record_user_transaction(db, user_id, -bet, 'casino', 'Облава СОБР в костях')
                    new_bal = await get_user_global_balance(db, user_id)
                    outcome_text = f"🚨 <b>ОБЛАВА В ИГОРНОМ КЛУБЕ!</b>\n{raid_notice['reason']}\n\n<i>{raid_notice['quote']}</i>\n\n📉 Ставка <code>-{bet} ₪</code> изъята в Казну Абу."
                    casino_engine.record_win_streak(user_id, False)
                else:
                    # Dynamic Anti-Streak / High-Roller Tilt
                    streak = casino_engine.get_win_streak(user_id)
                    win_threshold = 60 if (streak >= 3 or balance > 100_000) else 55

                    if result == 100:
                        win = bet * 3
                        tax_amt, actual_win = calculate_win_tax(win)
                        if tax_amt > 0: await add_to_abu_fund(db, int(tax_amt))
                        await add_user_global_balance(db, user_id, board_id, actual_win)
                        await record_user_transaction(db, user_id, actual_win, 'casino', f'Джекпот в кости (100/100)')
                        casino_engine.record_win_streak(user_id, True)
                        outcome_text = f"👑 <b>ДЖЕКПОТ 100/100!</b>\n🔥 Множитель x4! Чистый выигрыш: <code>+{actual_win} ₪</code>"
                    elif result >= win_threshold:
                        win = bet
                        tax_amt, actual_win = calculate_win_tax(win)
                        if tax_amt > 0: await add_to_abu_fund(db, int(tax_amt))
                        await add_user_global_balance(db, user_id, board_id, actual_win)
                        await record_user_transaction(db, user_id, actual_win, 'casino', f'Победа в кости ({result}/100)')
                        casino_engine.record_win_streak(user_id, True)
                        outcome_text = f"🎉 <b>ПОБЕДА!</b> Выпало {result} (≥{win_threshold}).\n💰 Ты поднял: <code>+{actual_win} ₪</code>"
                    else:
                        await deduct_user_global_balance(db, user_id, board_id, bet)
                        await add_to_abu_fund(db, bet)
                        await record_user_transaction(db, user_id, -bet, 'casino', f'Слив в костях ({result}/100)')
                        casino_engine.record_win_streak(user_id, False)
                        outcome_text = f"💀 <b>ПРОИГРЫШ!</b> Выпало {result} (&lt;{win_threshold}).\n📉 Ты слил: <code>-{bet} ₪</code>"

                    new_bal = await get_user_global_balance(db, user_id)

    if err_text:
        try:
            await callback.answer(err_text, show_alert=True)
        except Exception:
            pass
        return

    kb_again = InlineKeyboardMarkup(inline_keyboard=[
        [
            InlineKeyboardButton(text="🎲 Еще раз (та же ставка)", callback_data=f"dice_bet_{raw_bet}"),
            InlineKeyboardButton(text="🎰 Другая ставка", callback_data="economy_dice")
        ]
    ])
    caption = (
        f"🎲 <b>РЕЗУЛЬТАТ БРОСКА КОСТЕЙ</b>\n"
        f"Ставка: <code>{bet} ₪</code> | Выпало: <b>{result}/100</b>\n\n"
        f"{outcome_text}\n\n"
        f"💳 Новый баланс: <code>{int(new_bal)} ₪</code>"
    )
    from banner_manager import send_banner_message
    await send_banner_message(
        bot=callback.bot,
        chat_id=callback.message.chat.id,
        caption=caption,
        reply_markup=kb_again,
        category="roulette",
        parse_mode="HTML"
    )

# =============================================================================
# 🎰 ПОДПОЛЬНОЕ КАЗИНО ТГАЧА & 💸 ДРОП ШЕКЕЛЕЙ В ТРЕД (ЧЕКИ НА РЕАКЦИЮ)
# =============================================================================
import casino_engine
import drop_engine

@dp.message(Command("drop", "выбросить", "дроп", "чек", "throw", "giveaway"))
async def cmd_drop(message: types.Message, board_id: str | None, stream: str = 'ru'):
    """Команда /drop <сумма> — выбрасывает шекели в тред для быстрейшего клика."""
    if not board_id: return
    user_id = message.from_user.id
    db = await get_pool()
    balance = await get_user_global_balance(db, user_id)

    # Check if amount was passed directly in command arguments
    parts = (message.text or message.caption or "").split()
    if len(parts) > 1 and parts[1].isdigit():
        amount = int(parts[1])
        if amount < drop_engine.MIN_DROP_AMOUNT:
            await message.reply(drop_engine.get_min_drop_rejection_message(amount), parse_mode="HTML")
            return
        if amount > drop_engine.MAX_DROP_AMOUNT:
            await message.reply(drop_engine.get_max_drop_rejection_message(amount), parse_mode="HTML")
            return

        donor_name = f"Анон [{get_anon_id(user_id)}]"
        ok, msg, drop_rec = await drop_engine.create_money_drop(
            donor_id=user_id,
            donor_name=donor_name,
            board_id=board_id,
            amount=amount,
            db_lock=db_lock,
            db_conn=db,
            check_active_limit=True,
            check_board_flood=True,
        )
        if not ok or not drop_rec:
            await message.reply(msg, parse_mode="HTML")
            return

        kb = drop_engine.get_drop_claim_keyboard(drop_rec.drop_id, amount)
        caption = (
            f"💸 <b>ДРОП ШЕКЕЛЕЙ В ТРЕД!</b>\n\n"
            f"👤 <b>{donor_name}</b> выбросил <b>{amount} ₪</b> прямо в тред!\n"
            f"⚡ Кто первый нажмет на кнопку ниже — забирает весь куш себе!\n\n"
            f"⏳ <i>Дроп сгорит и вернется анону через 10 минут, если никто не заберет.</i>"
        )
        from banner_manager import send_banner_message
        donor_msg = await send_banner_message(
            bot=message.bot,
            chat_id=message.chat.id,
            caption=caption,
            reply_markup=kb,
            category="economy",
            parse_mode="HTML"
        )
        photo_payload = None
        if donor_msg:
            drop_engine.register_drop_message(drop_rec.drop_id, message.chat.id, donor_msg.message_id)
            if getattr(donor_msg, 'photo', None):
                photo_payload = donor_msg.photo[-1].file_id

        spawn_task(_broadcast_money_drop(message.bot, board_id, drop_rec.drop_id, message.chat.id, photo_payload, caption, kb))
        return

    # Interactive selector if no argument given
    kb = drop_engine.get_drop_creator_keyboard(int(balance))
    caption = (
        f"💸 <b>ДРОП ШЕКЕЛЕЙ В ТРЕД (ЧЕК НА СКОРОСТЬ)</b>\n\n"
        f"💳 Твой текущий баланс: <code>{int(balance)} ₪</code>\n"
        f"Выбери, сколько шекелей ты хочешь выбросить в тред для всех анонов:\n"
        f"<i>(Или введи команду с суммой, например: <code>/drop 500</code>)</i>"
    )
    from banner_manager import send_banner_message
    await send_banner_message(
        bot=message.bot,
        chat_id=message.chat.id,
        caption=caption,
        reply_markup=kb,
        category="economy",
        parse_mode="HTML"
    )

async def _broadcast_money_drop(bot, board_id: str, drop_id: str, exclude_chat_id: int, photo_payload, caption: str, kb):
    """Рассылает сообщение о дропе шекелей всем активным анонам на доске с аниме-баннером."""
    active_users = list(board_data.get(board_id, {}).get('users', {}).get('active', []))
    for target_uid in active_users:
        if target_uid != exclude_chat_id:
            try:
                if photo_payload:
                    sent = await bot.send_photo(
                        chat_id=target_uid,
                        photo=photo_payload,
                        caption=caption,
                        reply_markup=kb,
                        parse_mode="HTML"
                    )
                else:
                    sent = await bot.send_message(
                        chat_id=target_uid,
                        text=caption,
                        reply_markup=kb,
                        parse_mode="HTML"
                    )
                if sent:
                    drop_engine.register_drop_message(drop_id, target_uid, sent.message_id)
            except Exception:
                try:
                    sent = await bot.send_message(
                        chat_id=target_uid,
                        text=caption,
                        reply_markup=kb,
                        parse_mode="HTML"
                    )
                    if sent:
                        drop_engine.register_drop_message(drop_id, target_uid, sent.message_id)
                except Exception:
                    pass
            await asyncio.sleep(0.04)

async def _update_all_drop_messages(bot, drop_id: str, new_text: str, exclude_chat_id: Optional[int] = None, exclude_pair: Optional[Tuple[int, int]] = None):
    """Обновляет все копии сообщения о дропе у всех анонов, убирая кнопку и показывая победителя."""
    msg_copies = drop_engine.get_drop_messages(drop_id)
    for chat_id, message_id in msg_copies:
        if exclude_pair and (chat_id, message_id) == exclude_pair:
            continue
        if exclude_pair is None and exclude_chat_id is not None and chat_id == exclude_chat_id:
            continue
        try:
            try:
                await bot.edit_message_caption(
                    chat_id=chat_id,
                    message_id=message_id,
                    caption=new_text,
                    parse_mode="HTML",
                    reply_markup=None
                )
            except Exception:
                await bot.edit_message_text(
                    chat_id=chat_id,
                    message_id=message_id,
                    text=new_text,
                    parse_mode="HTML",
                    reply_markup=None
                )
        except Exception:
            pass
        await asyncio.sleep(0.04)

@dp.callback_query(F.data.startswith("drop:"))
async def cb_drop_handler(callback: types.CallbackQuery, board_id: str | None):
    if not board_id: return
    user_id = callback.from_user.id
    data = callback.data.split(":")
    action = data[1] if len(data) > 1 else ""
    db = await get_pool()

    if action == "claim":
        drop_id = data[2] if len(data) > 2 else ""
        claimer_name = f"Анон [{get_anon_id(user_id)}]"
        ok, msg, drop_rec = await drop_engine.claim_money_drop(
            drop_id=drop_id,
            claimer_id=user_id,
            claimer_name=claimer_name,
            claimer_board_id=board_id,
            db_lock=db_lock,
            db_conn=db,
            check_reaction_delay=True,
            check_claimer_rate_limit=True,
            check_farm_laundering=True,
            min_reaction_delay=1.0,
        )
        if not ok:
            await callback.answer(msg, show_alert=True)
            return

        await callback.answer(f"🎉 Ты успел забрать {int(drop_rec.amount)} ₪!", show_alert=True)
        new_text = (
            f"💸 <b>ДРОП ШЕКЕЛЕЙ ПЕРЕХВАЧЕН!</b>\n\n"
            f"👤 Создатель: <b>{drop_rec.donor_name}</b> (Сумма: <b>{int(drop_rec.amount)} ₪</b>)\n"
            f"🏆 Победитель: <b>{claimer_name}</b> оказался самым быстрым и забрал весь куш!\n\n"
            f"⚡ <i>Дроп закрыт.</i>"
        )
        # 1. Мгновенно обновляем у победителя
        try:
            if callback.message.caption:
                await callback.message.edit_caption(caption=new_text, parse_mode="HTML", reply_markup=None)
            else:
                await callback.message.edit_text(text=new_text, parse_mode="HTML", reply_markup=None)
        except Exception:
            pass

        # 2. Оповещаем автора в личку (только если автор не победитель)
        if drop_rec.donor_id and drop_rec.donor_id != user_id:
            try:
                await callback.bot.send_message(
                    chat_id=drop_rec.donor_id,
                    text=f"💸 <b>ТВОЙ ДРОП ЗАБРАЛИ!</b>\n\nАнон <b>{claimer_name}</b> только что перехватил твой дроп на <b>{int(drop_rec.amount)} ₪</b>!",
                    parse_mode="HTML"
                )
            except Exception:
                pass

        # 3. Фоново обновляем ВСЕ отправленные копии у автора и остальных анонов (без отдельного спам-поста на доску)
        winner_msg_pair = (callback.message.chat.id, callback.message.message_id) if callback.message else None
        spawn_task(_update_all_drop_messages(callback.bot, drop_id, new_text, exclude_chat_id=user_id, exclude_pair=winner_msg_pair))
        return

    elif action == "create":
        raw_amt = data[2] if len(data) > 2 else "0"
        amount = int(raw_amt) if raw_amt.isdigit() else 0
        if amount < drop_engine.MIN_DROP_AMOUNT:
            await callback.answer(drop_engine.get_min_drop_rejection_message(amount), show_alert=True)
            return
        if amount > drop_engine.MAX_DROP_AMOUNT:
            await callback.answer(drop_engine.get_max_drop_rejection_message(amount), show_alert=True)
            return

        donor_name = f"Анон [{get_anon_id(user_id)}]"
        ok, msg, drop_rec = await drop_engine.create_money_drop(
            donor_id=user_id,
            donor_name=donor_name,
            board_id=board_id,
            amount=amount,
            db_lock=db_lock,
            db_conn=db,
            check_active_limit=True,
            check_board_flood=True,
        )
        if not ok or not drop_rec:
            await callback.answer(msg, show_alert=True)
            return

        await callback.answer("✅ Дроп отправлен в тред!")
        kb = drop_engine.get_drop_claim_keyboard(drop_rec.drop_id, amount)
        caption = (
            f"💸 <b>ДРОП ШЕКЕЛЕЙ В ТРЕД!</b>\n\n"
            f"👤 <b>{donor_name}</b> выбросил <b>{amount} ₪</b> прямо в тред!\n"
            f"⚡ Кто первый нажмет на кнопку ниже — забирает весь куш себе!\n\n"
            f"⏳ <i>Дроп сгорит и вернется анону через 10 минут, если никто не заберет.</i>"
        )
        try:
            await callback.message.delete()
        except Exception:
            pass

        from banner_manager import send_banner_message
        donor_msg = await send_banner_message(
            bot=callback.bot,
            chat_id=callback.message.chat.id,
            caption=caption,
            reply_markup=kb,
            category="economy",
            parse_mode="HTML"
        )
        photo_payload = None
        if donor_msg:
            drop_engine.register_drop_message(drop_rec.drop_id, callback.message.chat.id, donor_msg.message_id)
            if getattr(donor_msg, 'photo', None):
                photo_payload = donor_msg.photo[-1].file_id

        spawn_task(_broadcast_money_drop(callback.bot, board_id, drop_rec.drop_id, callback.message.chat.id, photo_payload, caption, kb))
        return

    elif action == "cancel_menu":
        try:
            await callback.message.delete()
        except Exception:
            await callback.answer("Отменено")


