@dp.message(Command("slop", "roast", "roasts", "слоп", "нейрослоп", ignore_case=True, ignore_mention=True))
async def cmd_toggle_ai_slop(message: types.Message, board_id: str | None, stream: str = 'ru'):
    """
    Команда быстрого включения/выключения AI-роастов и нейрослопа (/slop on / off / hide / show).
    """
    if not board_id: return
    args = (message.text or message.caption or "").split()
    user_id = message.from_user.id
    lang = stream if ENABLE_MULTILANG else ('en' if board_id == 'int' else 'ru')
    b_data = board_data[board_id]
    if user_id not in b_data.get('user_settings', {}):
        b_data.setdefault('user_settings', {})[user_id] = {'nsfw': False, 'hide': set(), 'disable_ai_roasts': False, 'hide_ai_slop': False}
    current_status = bool(b_data['user_settings'][user_id].get('disable_ai_roasts') or b_data['user_settings'][user_id].get('hide_ai_slop'))
    if len(args) < 2:
        status_str = ("Скрыт 🚫" if current_status else "Включен 👁") if lang == 'ru' else ("Hidden 🚫" if current_status else "Enabled 👁")
        if lang == 'en':
            msg = f"Current AI Roasts / Slop filter status: <b>{status_str}</b>.\nUsage: <code>/slop hide</code> (or <code>/slop on</code>) / <code>/slop show</code> (or <code>/slop off</code>)"
        elif lang == 'jp':
            msg = f"現在のAI煽り・スロップ設定: <b>{status_str}</b>\n使い方: <code>/slop hide</code> または <code>/slop show</code>"
        else:
            msg = f"Текущий статус фильтра AI-разъёбов / нейрослопа: <b>{status_str}</b>.\nИспользование: <code>/slop hide</code> (скрыть) или <code>/slop show</code> (показывать)"
        await message.answer(msg, parse_mode="HTML")
        return
    action = args[1].lower()
    new_status = None
    if action in ['on', 'enable', 'hide', '1', 'вкл', 'скрыть', 'disable_roasts', 'mute']:
        new_status = True
    elif action in ['off', 'disable', 'show', '0', 'выкл', 'показать', 'enable_roasts', 'unmute']:
        new_status = False
    if new_status is not None:
        b_data['user_settings'][user_id]['disable_ai_roasts'] = new_status
        b_data['user_settings'][user_id]['hide_ai_slop'] = new_status
        spawn_task(update_user_settings_db(user_id, board_id, disable_ai_roasts=1 if new_status else 0, hide_ai_slop=1 if new_status else 0))
        if lang == 'en':
            reply = "🚫 AI Roasts and Neuro-Slop are now hidden." if new_status else "👁 AI Roasts and Neuro-Slop are now enabled."
        elif lang == 'jp':
            reply = "🚫 AI煽り・スロップを非表示にしました。" if new_status else "👁 AI煽り・スロップを表示します。"
        else:
            reply = "🚫 AI-разъёбы и нейрослоп теперь скрыты." if new_status else "👁 AI-разъёбы и нейрослоп теперь включены."
        await message.answer(reply)
    else:
        err = "Error: Use 'hide' / 'on' or 'show' / 'off'." if lang != 'ru' else "Ошибка: Используйте 'hide' / 'on' или 'show' / 'off'."
        await message.answer(err)
@dp.message(Command("whois", "info"))
async def cmd_whois(message: types.Message, board_id: str | None, stream: str = 'ru'):
    if not board_id or not is_admin(message.from_user.id, board_id):
        try:
            await message.delete()
        except Exception:
            pass
        return
    target_id = None
    if message.reply_to_message:
        target_id = await get_author_id_by_reply(message)
    elif len((message.text or message.caption or "").split()) > 1:
        try: target_id = int((message.text or message.caption or "").split()[1])
        except Exception: pass
    lang = stream if ENABLE_MULTILANG else ('en' if board_id == 'int' else 'ru')
    if not target_id:
        await message.answer("ID needed." if lang == 'en' else "Нужен ID.")
        return
        
    anon_name = generate_anon_name(target_id)
    balance = 0
    post_count = 0
    try:
        async with db_lock:
            db = await get_pool()
            async with db.execute("SELECT SUM(balance) FROM Users WHERE user_id = ?", (target_id,)) as cursor:
                row = await cursor.fetchone()
                balance = row[0] if row and row[0] else 0
            async with db.execute("SELECT COUNT(*) FROM Posts WHERE author_id = ?", (target_id,)) as cursor:
                row = await cursor.fetchone()
                post_count = row[0] if row and row[0] else 0
    except Exception as e:
        logger.error(f"Error fetching whois info: {e}", exc_info=True)

    if lang == 'en': header = f"🗂 <b>Dossier on {anon_name}:</b>\n<code>{'—'*20}</code>"
    elif lang == 'jp': header = f"🗂 <b>{anon_name} の調査書:</b>\n<code>{'—'*20}</code>"
    else: header = f"🗂 <b>Досье на {anon_name}:</b>\n<code>{'—'*20}</code>"
    
    report = [header]
    report.append(f"🆔 <b>ID:</b> <code>{target_id}</code>")
    report.append(f"💸 <b>Баланс:</b> {int(balance)} RUB")
    report.append(f"💩 <b>Постов:</b> {post_count}")
    report.append(f"<code>{'—'*20}</code>")

    total_activity = False
    now_dt = datetime.now(UTC)
    for b_id in BOARDS:
        b_data = board_data[b_id]
        status = []
        if target_id in b_data['users']['banned']:
            status.append("🚫 BAN")
        elif target_id in b_data['users']['active']:
            status.append("✅ Active")
            
        mute_end = b_data['mutes'].get(target_id, datetime.min.replace(tzinfo=UTC))
        if mute_end > now_dt:
            td = mute_end - now_dt
            status.append(f"🔇 Mute ({int(td.total_seconds()//60)}m)")
            
        smute_end = b_data['shadow_mutes'].get(target_id, datetime.min.replace(tzinfo=UTC))
        if smute_end > now_dt:
            td = smute_end - now_dt
            status.append(f"👻 Shadow ({int(td.total_seconds()//60)}m)")
            
        u_set = b_data.get('user_settings', {}).get(target_id, {})
        if u_set.get('shadow_gif'): status.append("NoGIF")
        if u_set.get('shadow_sticker'): status.append("NoSticker")
        if u_set.get('lie_media'): status.append("LieMedia")
        spam_v_data = b_data.get('spam_violations', {}).get(target_id, {})
        spam_level = spam_v_data.get('level', 0) if isinstance(spam_v_data, dict) else 0
        if spam_level > 0: status.append(f"⚠️ Spam Level: {spam_level}")
        
        if status:
            total_activity = True
            board_name = BOARD_CONFIG[b_id]['name']
            report.append(f"<b>{board_name}</b>: {', '.join(status)}")
            
    if not total_activity:
        if lang == 'en': report.append("<i>No info (not active on any board).</i>")
        elif lang == 'jp': report.append("<i>情報なし（どの板でも活動していません）。</i>")
        else: report.append("<i>Информации нет (не активен ни на одной доске).</i>")
        
    await message.answer("\n".join(report), parse_mode="HTML")
@dp.message(Command("unpin"))
async def cmd_global_unpin(message: types.Message, board_id: str | None, stream: str = 'ru'):
    """
    Снимает закреп и удаляет его из памяти/БД.
    """
    if not board_id or not is_admin(message.from_user.id, board_id): return
    lang = stream if ENABLE_MULTILANG else ('en' if board_id == 'int' else 'ru')
    b_data = board_data[board_id]
    old_pin = b_data.get('active_pin')
    b_data['active_pin'] = None
    await update_board_settings(board_id, {'active_pin': None})
    target_post_num = None
    if message.reply_to_message:
        # Под локом только чтение карты message_to_post. Запрос к БД (фолбэк,
        # когда пост уже выгружен из RAM) вынесен наружу: раньше он выполнялся
        # удерживая storage_lock.
        async with storage_lock:
            key = (message.chat.id, message.reply_to_message.message_id)
            target_post_num = message_to_post.get(key)
        if not target_post_num:
            post_info = await get_post_info_by_copy(message.chat.id, message.reply_to_message.message_id)
            if post_info: target_post_num = post_info[0]
    else:
        target_post_num = old_pin
    if not target_post_num:
        msg = "✅ Pin reset in DB. No active post found to unpin." if lang == 'en' else ("✅ DBのピン留めをリセットしました。解除する投稿が見つかりません。" if lang == 'jp' else "✅ Закреп сброшен в БД. Активных постов для открепления не найдено.")
        await message.answer(msg)
        return
    msg_start = f"❌ Unpinning post #{target_post_num}..." if lang == 'en' else (f"❌ 投稿 #{target_post_num} のピン留めを解除中..." if lang == 'jp' else f"❌ Снимаю закреп поста #{target_post_num}...")
    status_msg = await message.answer(msg_start)
    copies = await get_post_copies(target_post_num)
    if copies:
        async def unpin_one(uid, mid):
            try:
                await message.bot.unpin_chat_message(chat_id=uid, message_id=mid)
                return True
            except Exception: return False
        CHUNK_SIZE = 40
        count = 0
        for i in range(0, len(copies), CHUNK_SIZE):
            chunk = copies[i:i + CHUNK_SIZE]
            res = await asyncio.gather(*[unpin_one(uid, mid) for uid, mid in chunk])
            count += sum(res)
            await asyncio.sleep(1.0)
        await log_global_event('bot', f"📍 UNPIN: Админ {message.from_user.id} снял закреп поста #{target_post_num} на /{board_id}/")
        if lang == 'en': final = f"✅ Post #{target_post_num} unpinned for {count} users."
        elif lang == 'jp': final = f"✅ 投稿 #{target_post_num} のピン留めを {count} 人のユーザーから解除しました。"
        else: final = f"✅ Пост #{target_post_num} откреплен у {count} юзеров. Из памяти удален."
        await status_msg.edit_text(final)
    else:
        if lang == 'en': final = f"✅ Post #{target_post_num} removed from pin settings."
        elif lang == 'jp': final = f"✅ 投稿 #{target_post_num} をピン留め設定から削除しました。"
        else: final = f"✅ Пост #{target_post_num} удален из настроек закрепа."
        await status_msg.edit_text(final)
_MOTIVATION_STATE_FILE = os.path.join(DATA_DIR, "motivation_broadcast_state.json")

def _load_motivation_state() -> dict:
    try:
        if os.path.exists(_MOTIVATION_STATE_FILE):
            with open(_MOTIVATION_STATE_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return {}

def _save_motivation_state(state: dict):
    try:
        os.makedirs(os.path.dirname(_MOTIVATION_STATE_FILE), exist_ok=True)
        with open(_MOTIVATION_STATE_FILE, "w", encoding="utf-8") as f:
            json.dump(state, f)
    except Exception:
        pass

def _get_last_motivation_time(board_id: str) -> float:
    st = _load_motivation_state()
    return float(st.get(board_id, 0.0))

def _set_last_motivation_time(board_id: str, ts: float):
    st = _load_motivation_state()
    st[board_id] = ts
    _save_motivation_state(st)

async def _send_motivation_message(board_id: str, stream: str, recipients: set):
    """
    Sends a motivational message, auto graphic invite card, or site promo to active users.
    Pre-uploads generated invite images (rendered with authentic slogans + random user post photos from DB)
    to obtain a real Telegram file_id for instant fanout.
    """
    rand_choice = random.random()
    board_username = BOARD_CONFIG.get(board_id, {}).get('username', '@dvach_chatbot')
    site_url = f"https://tgach.top/{board_id}/"

    if rand_choice < 0.15:
        # 1. Реклама веб-версии
        if stream == 'en':
            text_body = random.choice(SITE_PROMO_PHRASES_EN)
            btn_text = "🔗 Open Website"
        elif stream == 'jp':
            text_body = random.choice(SITE_PROMO_PHRASES_JP)
            btn_text = "🔗 サイトを開く"
        else:
            text_body = random.choice(SITE_PROMO_PHRASES)
            btn_text = "🔗 Перейти на сайт"

        message_text = f"{text_body}\n\n👉 <a href='{site_url}'>{site_url}</a>"
        keyboard = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text=btn_text, url=site_url)]
        ])
        from banner_manager import get_banner_file
        fname, photo_payload = get_banner_file(category="calm")
        from banner_manager import _BANNER_CACHE
        fid = photo_payload if isinstance(photo_payload, str) else _BANNER_CACHE.get(fname)
        if not fid and _BANNER_CACHE:
            fid = next(iter(_BANNER_CACHE.values()), None)
        content = {
            'type': 'photo' if fid else 'text',
            'file_id': fid,
            'caption': message_text,
            'text': message_text,
            'is_system_message': True,
            'archive_allowed': True
        }

    elif rand_choice < 0.85:
        # 2. Автоматическая генерация графической инвайт-карточки ("Позови друзей")
        from invite_image_generator import generate_invite_image_async, get_random_auto_invite_content
        slogan, companion_caption = get_random_auto_invite_content(board_id=board_id, bot_username=board_username)
        site_btn = "🌐 Web Version" if stream == 'en' else ("🌐 ウェブ版" if stream == 'jp' else "🌐 Веб-версия")
        pic_btn = "🖼 Graphic Invite" if stream == 'en' else ("🖼 QR画像" if stream == 'jp' else "🖼 Картинка с QR")

        keyboard = InlineKeyboardMarkup(inline_keyboard=[
            [
                InlineKeyboardButton(text=site_btn, url=site_url),
                InlineKeyboardButton(text=pic_btn, callback_data=f"gen_invite_pic:{board_id}")
            ]
        ])

        file_id = None
        try:
            from common.config import STORAGE_CHANNELS
            bot = GLOBAL_BOTS.get(board_id) or shared_state.GLOBAL_BOTS.get(board_id)
            buf = await generate_invite_image_async(board_id=board_id, bot_username=board_username, slogan_dict=slogan, bot=bot)
            raw_bytes = buf.getvalue() if buf else None

            # Загружаем сгенерированную карточку 1 раз в Telegram для получения file_id
            storage_channel = (STORAGE_CHANNELS.get(stream) if isinstance(STORAGE_CHANNELS, dict) else None) or ARCHIVE_CHANNEL_ID
            if bot and storage_channel and raw_bytes:
                try:
                    from aiogram.types import BufferedInputFile
                    input_file = BufferedInputFile(raw_bytes, filename=f"invite_{board_id}.jpg")
                    upload_msg = await bot.send_photo(storage_channel, input_file, caption=f"🖼 Invite Card #{board_id}")
                    if upload_msg and upload_msg.photo:
                        file_id = upload_msg.photo[-1].file_id
                except Exception as upload_err:
                    logger.warning(f"Failed to pre-upload invite image to storage channel: {upload_err}")

            content = {
                'type': 'photo' if (file_id or raw_bytes) else 'text',
                'file_id': file_id,
                'image_bytes': raw_bytes if not file_id else None,
                'caption': companion_caption,
                'text': companion_caption,
                'is_system_message': True,
                'archive_allowed': True
            }
        except Exception as e:
            logger.error(f"Error generating auto invite image: {e}", exc_info=True)
            content = {'type': 'text', 'text': companion_caption, 'is_system_message': True}

    else:
        # 3. Текстовая мотивация/инвайт
        if stream == 'en':
            motivation = random.choice(MOTIVATIONAL_MESSAGES_EN)
            invite_text = random.choice(INVITE_TEXTS_EN)
            copy_lbl = "Copy and send to anons:"
            site_btn = "🌐 Web Version"
            pic_btn = "🖼 Graphic Invite"
        elif stream == 'jp':
            motivation = random.choice(MOTIVATIONAL_MESSAGES_JP)
            invite_text = random.choice(INVITE_TEXTS_JP)
            copy_lbl = "コピーしてアノンに送信:"
            site_btn = "🌐 ウェブ版"
            pic_btn = "🖼 QR画像"
        else:
            motivation = random.choice(MOTIVATIONAL_MESSAGES)
            invite_text = random.choice(INVITE_TEXTS)
            copy_lbl = "Скопируй и отправь анончикам:"
            site_btn = "🌐 Веб-версия"
            pic_btn = "🖼 Картинка с QR"

        message_text = (
            f"💭 {motivation}\n\n"
            f"{copy_lbl}\n"
            f"<code>{escape_html(invite_text)}</code>"
        )
        keyboard = InlineKeyboardMarkup(inline_keyboard=[
            [
                InlineKeyboardButton(text=site_btn, url=site_url),
                InlineKeyboardButton(text=pic_btn, callback_data=f"gen_invite_pic:{board_id}")
            ]
        ])
        file_id = None
        from banner_manager import get_banner_file, _BANNER_CACHE
        banner_cat = random.choice(["calm", "maid", "night", "start", "digest"])
        fname, photo_payload = get_banner_file(category=banner_cat)
        file_id = photo_payload if isinstance(photo_payload, str) else _BANNER_CACHE.get(fname)
        if not file_id and _BANNER_CACHE:
            file_id = next(iter(_BANNER_CACHE.values()), None)

        content = {
            'type': 'photo' if file_id else 'text',
            'file_id': file_id,
            'caption': message_text,
            'text': message_text,
            'is_system_message': True,
            'archive_allowed': True
        }

    now_dt = datetime.now(UTC)

    post_num = await create_post(
        board_id=board_id, author_id=0, content=content,
        timestamp=now_dt.timestamp(), is_from_site=False, stream=stream
    )

    if not post_num: return

    header = await format_header(board_id, post_num)
    if board_id != 'int': header = f"### АДМИН ###\n{header}"
    content['header'] = header

    await update_post_content(post_num, content)
    async with storage_lock:
        messages_storage[post_num] = {
            'author_id': 0, 'timestamp': now_dt,
            'content': content, 'board_id': board_id
        }

    # Передаем keyboard в очередь
    await enqueue_board_message(board_id, {
        'recipients': recipients,
        'content': content,
        'post_num': post_num,
        'board_id': board_id,
        'keyboard': keyboard
    })
    target_bot = GLOBAL_BOTS.get(board_id) or shared_state.GLOBAL_BOTS.get(board_id) or GLOBAL_BOTS.get('b')
    if target_bot:
        spawn_task(_forward_post_to_realtime_archive(
            bot_instance=target_bot,
            board_id=board_id,
            post_num=post_num,
            content=content,
            is_shadow_muted=False,
            stream=stream
        ))


async def _board_motivation_worker(board_id: str):
    """
    Worker loop to check activity and periodically trigger motivation and invite card messages
    regularly every 3-4 hours (with soft random jitter).
    """
    # Небольшая пауза при старте, чтобы все боты успели инициализироваться
    await asyncio.sleep(random.randint(15, 60))

    while True:
        try:
            now = time.time()
            last_time = _get_last_motivation_time(board_id)
            # Регулярный интервал рассылки пичей: 3-4 часа (10800 - 14400 сек)
            target_interval = 10800.0 # 3 часа минимум

            elapsed = now - last_time
            if elapsed < target_interval and last_time > 0:
                # Если интервал еще не прошел с прошлой рассылки, спим оставшееся время
                wait_time = max(30.0, min(target_interval - elapsed, 600.0))
                await asyncio.sleep(wait_time)
                continue

            # Проверка активности: пропускаем только полностью мертвые доски (activity < 1)
            activity = await get_board_activity_last_hours(board_id, hours=12)
            if activity < 1:
                await asyncio.sleep(600)
                continue

            b_data = board_data.get(board_id)
            if not b_data:
                await asyncio.sleep(300)
                continue

            streams_to_process = ['ru'] # По дефолту
            if board_id == 'int':
                streams_to_process = ['en']
            elif ENABLE_MULTILANG:
                streams_to_process = ['ru', 'en', 'jp']

            sent_any = False
            for stream in streams_to_process:
                if board_id == 'int':
                    recipients = b_data.get('users', {}).get('active', set()) - b_data.get('users', {}).get('banned', set())
                else:
                    if ENABLE_MULTILANG:
                        stream_users = await get_stream_active_users(board_id, stream)
                        recipients = stream_users.intersection(b_data.get('users', {}).get('active', set())) - b_data.get('users', {}).get('banned', set())
                    else:
                        recipients = b_data.get('users', {}).get('active', set()) - b_data.get('users', {}).get('banned', set())
                if not recipients:
                    continue

                await _send_motivation_message(board_id, stream, recipients)
                sent_any = True

            if sent_any:
                _set_last_motivation_time(board_id, time.time())
                # После успешной отправки следующая рассылка через 3-4 часа (10800 - 14400 сек)
                next_sleep = random.randint(10800, 14400)
                await asyncio.sleep(next_sleep)
            else:
                await asyncio.sleep(600)

        except Exception as e:
            logger.error(f"❌ [{board_id}] Ошибка в motivation_broadcaster: {e}", exc_info=True)
            await asyncio.sleep(300)


async def motivation_broadcaster():
    """
    Main entry point to start motivation workers for all boards.
    """
    await asyncio.sleep(15)  # Начальная задержка
    tasks = [spawn_task(_board_motivation_worker(bid)) for bid in BOARDS if bid != 'test']
    await asyncio.gather(*tasks)

async def fetch_dvach_thread(board: str, only_new: bool = False) -> dict | None:
    try:
        timeout = aiohttp.ClientTimeout(total=10)
        async with aiohttp.ClientSession(timeout=timeout, connector=aiohttp.TCPConnector(ssl=False), connector_owner=True) as session:
            headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
            async with session.get(f'https://2ch.hk/{board}/catalog.json', headers=headers) as response:
                if response.status != 200:
                    return None
                data = await response.json()
                if not data or 'threads' not in data:
                    return None
                threads = data['threads']
                if not threads:
                    return None
                if only_new and board == 'news':
                    threads.sort(key=lambda x: x.get('timestamp', 0), reverse=True)
                    threads = threads[:10]
                thread = random.choice(threads)
                thread_num = thread.get('num')
                if not thread_num:
                    return None
                async with session.get(f'https://2ch.hk/{board}/res/{thread_num}.json', headers=headers) as thread_response:
                    if thread_response.status != 200:
                        return None
                    thread_data = await thread_response.json()
                    if not thread_data or 'threads' not in thread_data:
                        return None
                    posts = thread_data['threads'][0]['posts']
                    if not posts:
                        return None
                    op_post = posts[0]
                    raw_comment = op_post.get('comment', '')
                    raw_subject = op_post.get('subject', '')
                    
                    # Чистим HTML разметку сосача
                    text = raw_comment
                    text = text.replace('<br>', '\n').replace('<br/>', '\n').replace('<br />', '\n')
                    text = re.sub(r'<[^>]+>', '', text)
                    text = html.unescape(text)
                    text = text.replace('&gt;', '>').replace('&lt;', '<').replace('&amp;', '&').replace('&quot;', '"')
                    text = re.sub(r'\n{3,}', '\n\n', text).strip()
                    
                    if len(text) > 1200:
                        text = text[:1200] + '...'
                    
                    title = raw_subject.strip() if raw_subject else ""
                    if not title:
                        clean_lines = [l.strip() for l in text.split('\n') if l.strip() and not l.strip().startswith('>')]
                        title = clean_lines[0][:60] if clean_lines else f"Тред с 2ch.hk /{board}/"
                    
                    link = f"https://2ch.hk/{board}/res/{thread_num}.html"
                    posts_count = len(posts)
                    
                    formatted_text = (
                        f"📌 <b>[ИМПОРТИРОВАННЫЙ ТРЕД С 2CH.HK /{board}/]</b>\n"
                        f"<b>{escape_html(title)}</b>\n\n"
                        f"{escape_html(text)}\n\n"
                        f"📊 <i>Постов на 2ch: {posts_count} | 🔗 <a href='{link}'>Открыть тред на 2ch.hk</a></i>"
                    )
                    
                    return {
                        'title': title,
                        'text': formatted_text,
                        'link': link,
                        'board': board,
                        'thread_num': thread_num,
                        'posts_count': posts_count
                    }
    except Exception as e:
        logger.error(f"Ошибка получения треда с /{board}/: {e}", exc_info=True)
        return None
async def format_thread_for_telegram(op_post: dict, replies: list[dict]) -> list[str]:
    if not op_post: return []
    op_title = clean_html_tags(op_post['content'].get('text', ''))
    op_media = "\n[изображение]" if op_post['content'].get('type') != 'text' else ""
    parts = [f"<b>Тред #{op_post['id']}: {escape_html(op_title)}</b>{op_media}\n\n"]
    total_posts = len(replies) + 1
    for i, reply in enumerate(replies):
        header = f"Пост #{reply['id']}, {format_timestamp(reply['timestamp'])}, {i + 2}/{total_posts}"
        reply_to = f">>{reply['reply_to_post_num']}\n" if reply['reply_to_post_num'] else ""
        media = "[изображение]\n" if reply['content'].get('type') != 'text' else ""
        text = escape_html(clean_html_tags(reply['content'].get('text', '')))
        parts.append(f"<i>{header}</i>\n{reply_to}{media}{text}\n\n")
    parts.append("\n\n<i>(Этот тред открыт в режиме только для чтения)</i>")
    full_text = "".join(parts)
    return split_text(full_text, 4096)
def format_timestamp(ts: float) -> str:

    try:
        return datetime.fromtimestamp(ts, tz=UTC).strftime('%d.%m.%y %H:%M')
    except (ValueError, TypeError, OverflowError, OSError):
        return ""
async def dvach_thread_poster():
    """
    Периодически постит случайный тред с 2ch как ПОЛНОЦЕННЫЙ ТРЕД.
    """
    await asyncio.sleep(300) 
    SOURCE_BOARDS = ['b', 'po', 'a', 'sex', 'vg', 'news']
    while True:
        try:
            delay = random.randint(7200, 18000)
            await asyncio.sleep(delay)
            destination_board_id = random.choice([b_id for b_id in BOARDS if b_id not in ['test']])
            activity = await get_board_activity_last_hours(destination_board_id, hours=24)
            if activity < 2: continue 
            b_data = board_data[destination_board_id]
            recipients = b_data['users']['active'] - b_data['users']['banned']
            if not recipients: continue
            
            thread_info = await fetch_dvach_thread(random.choice(SOURCE_BOARDS))
            if not thread_info or not thread_info.get('text'): continue
            
            thread_text = thread_info['text']
            title = thread_info.get('title', 'Тред с 2ch')[:50]
            link = thread_info.get('link', 'https://2ch.hk/')
            
            now_dt = datetime.now(UTC)
            thread_id = secrets.token_hex(4)
            await create_thread(
                thread_id=thread_id,
                board_id=destination_board_id,
                op_id=0, # Системный
                title=title,
                created_at=now_dt.timestamp(),
                stream='ru'
            )
            if destination_board_id in THREAD_BOARDS:
                set_thread_info(destination_board_id, thread_id, {
                    'op_id': 0, 'title': title, 'created_at': now_dt.isoformat(),
                    'last_activity_at': now_dt.timestamp(), 'posts': [], 
                    'subscribers': set(), 'is_archived': False, 'stream': 'ru'
                })
            
            from banner_manager import get_banner_file
            fname, photo_payload = get_banner_file(category="digest")
            from banner_manager import _BANNER_CACHE
            fid = photo_payload if isinstance(photo_payload, str) else _BANNER_CACHE.get(fname)
            if not fid and _BANNER_CACHE:
                fid = next(iter(_BANNER_CACHE.values()), None)
            
            keyboard = InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🔗 Открыть на 2ch.hk", url=link)]
            ])
            
            content = {
                'type': 'photo' if fid else 'text',
                'file_id': fid,
                'caption': thread_text,
                'text': thread_text,
                'is_system_message': True,
                'archive_allowed': True
            }
            post_num = await create_post(
                board_id=destination_board_id,
                author_id=0,
                content=content,
                timestamp=now_dt.timestamp(),
                is_from_site=False, 
                stream='ru',
                thread_id_from_bot=thread_id # Привязываем к треду
            )
            if post_num:
                if destination_board_id in THREAD_BOARDS:
                    get_thread_info(destination_board_id, thread_id)['posts'].append(post_num)
                header = await format_header(destination_board_id, post_num)
                header_with_source = f"{header} (2ch.hk Import)"
                content['header'] = header_with_source
                await update_post_content(post_num, content)
                async with storage_lock:
                    messages_storage[post_num] = {
                        'author_id': 0,
                        'timestamp': now_dt,
                        'content': content,
                        'board_id': destination_board_id,
                        'thread_id': thread_id
                    }
                await enqueue_board_message(destination_board_id, {
                    'recipients': recipients,
                    'content': content,
                    'post_num': post_num,
                    'board_id': destination_board_id,
                    'thread_id': thread_id,
                    'keyboard': keyboard
                })
                logger.info(f"✅ Импортирован тред #{thread_id} (пост #{post_num}) на доску {destination_board_id}")
        except Exception as e:
            logger.error(f"❌ Ошибка в dvach_thread_poster: {e}", exc_info=True)
            await asyncio.sleep(300)
async def check_cooldown(message: Message, board_id: str) -> bool:

    if board_id == 'trash':
        return True # Для доски-мусорки кулдауна нет, всегда разрешаем
    if message.from_user and is_admin(message.from_user.id, board_id):
        return True
    b_data = board_data[board_id]
    last_activation = b_data.get('last_mode_activation')
    if last_activation is None:
        return True
    elapsed = (datetime.now(UTC) - last_activation).total_seconds()
    if elapsed < MODE_COOLDOWN:
        time_left = MODE_COOLDOWN - elapsed
        minutes = int(time_left // 60)
        seconds = int(time_left % 60)
        lang = 'en' if board_id == 'int' else 'ru'
        if lang == 'en':
            phrases = [
                "⏳ Hey faggot, slow down! Modes on this board can be switched once per hour.\nWait for: {minutes} minutes {seconds} seconds.",
                "⌛️ Cool down, cowboy. The mode switch is on cooldown.\nTime left: {minutes}m {seconds}s.",
                "⛔️ You're switching modes too often, cunt. Wait another {minutes} minutes {seconds} seconds.",
                "⚠️ Wait, I need to rest. You can switch modes in {minutes}m {seconds}s."
            ]
        else:
            phrases = [
                "⏳ Эй пидор, не спеши! Режимы на этой доске можно включать раз в час.\nЖди еще: {minutes} минут {seconds} секунд\n\nА пока посиди в углу и подумай о своем поведении.",
                "⌛️ Остынь, ковбой. Кулдаун на смену режима еще не прошел.\nОсталось: {minutes}м {seconds}с.",
                "⛔️ Слишком часто меняешь режимы, заебал. Подожди еще {minutes} минут {seconds} секунд.",
                "⚠️ Подожди, я отдохну. Режимы можно будет переключить через {minutes}м {seconds}с.",
                "💤 Пора отдохнуть с режимами, не мешай мне. Я устал.",
                "О, боже, как же я устал от этих режимов. Иди отдохни."
            ]
        text = random.choice(phrases).format(minutes=minutes, seconds=seconds)
        try:
            sent_msg = await message.answer(text, parse_mode="HTML")
            spawn_task(delete_message_after_delay(sent_msg, 11))
        except Exception:
            logger.error(f"Error sending cooldown msg: {traceback.format_exc()}")
        try:
            await message.delete()
        except Exception:
            pass
        return False
    return True
def get_board_id(telegram_object: types.Message | types.CallbackQuery) -> str | None:
    """
    Мгновенно определяет ID доски ('b', 'po', etc.) по токену бота,
    используя предвычисленную карту.
    """
    try:
        bot_token = telegram_object.bot.token
        return TOKEN_TO_BOARD_MAP.get(bot_token)
    except AttributeError:
        return None
GRAPH_STATS_PATH = "graph.json"
GRAPH_STATS_BACKUP_PATH = "graph.json.bak"
GRAPH_STATS_RETENTION_DAYS = 90  # /graph принимает максимум 30d, держим тройной запас


def _sync_save_graph_stats(data_to_save: dict) -> bool:
    """
    Атомарно сохраняет статистику графика на диск.

    Пишем во временный файл в той же директории, фсинкаем и только потом
    подменяем боевой через os.replace (атомарен на Windows и POSIX).
    Так внезапный SIGINT от memory_restarter не может оставить обрезанный
    graph.json. Предыдущая удачная версия сохраняется в .bak.
    """
    tmp_path = ""
    try:
        directory = os.path.dirname(os.path.abspath(GRAPH_STATS_PATH))
        fd, tmp_path = tempfile.mkstemp(prefix=".graph_", suffix=".tmp", dir=directory)
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            json.dump(data_to_save, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())

        # Ротация бэкапа перед подменой: если новый файл окажется плохим,
        # load_graph_stats поднимет предыдущий.
        if os.path.exists(GRAPH_STATS_PATH):
            try:
                shutil.copyfile(GRAPH_STATS_PATH, GRAPH_STATS_BACKUP_PATH)
            except OSError as e:
                logger.warning(f"[graph_saver] Не удалось обновить {GRAPH_STATS_BACKUP_PATH}: {e}")

        os.replace(tmp_path, GRAPH_STATS_PATH)
        tmp_path = ""
        return True
    except Exception as e:
        logger.error(f"⛔ Ошибка в потоке сохранения graph.json: {e}", exc_info=True)
        return False
    finally:
        if tmp_path:
            try:
                os.remove(tmp_path)
            except OSError:
                logger.error(f"Error removing temp file: {traceback.format_exc()}")


def _coerce_graph_stats(raw) -> dict:
    """
    Приводит загруженный JSON к ожидаемой форме {board_id: {iso_ts: int}}.

    Файл могли отредактировать руками или он мог прийти из старой версии,
    поэтому не доверяем структуре: _prepare_graph_data и graph_data_collector
    падают на любом не-dict значении.
    """
    if not isinstance(raw, dict):
        return {}
    cleaned = {}
    for board_id, series in raw.items():
        if not isinstance(board_id, str) or not isinstance(series, dict):
            continue
        board_series = {}
        for ts_key, count in series.items():
            if not isinstance(ts_key, str):
                continue
            if isinstance(count, bool) or not isinstance(count, (int, float)):
                continue
            board_series[ts_key] = int(count)
        if board_series:
            cleaned[board_id] = board_series
    return cleaned


def _prune_graph_stats(data: dict, retention_days: int = GRAPH_STATS_RETENTION_DAYS) -> int:
    """Выбрасывает точки старше retention_days. Возвращает число удалённых."""
    cutoff = datetime.now(UTC) - timedelta(days=retention_days)
    removed = 0
    for board_id in list(data.keys()):
        series = data[board_id]
        for ts_key in list(series.keys()):
            try:
                point_dt = datetime.fromisoformat(ts_key)
            except ValueError:
                # Нераспознаваемый ключ — он всё равно уронит pd.to_datetime
                series.pop(ts_key, None)
                removed += 1
                continue
            if point_dt.tzinfo is None:
                point_dt = point_dt.replace(tzinfo=UTC)
            if point_dt < cutoff:
                series.pop(ts_key, None)
                removed += 1
        if not series:
            data.pop(board_id, None)
    return removed


def _report_graph_save_result(future) -> None:
    """Callback для run_in_executor: не даём ошибке записи утонуть без следа."""
    try:
        if future.result() is False:
            logger.warning("⚠️ graph.json не сохранён (см. ошибку выше), данные остались только в RAM.")
    except Exception as e:
        logger.error(f"⛔ Поток сохранения graph.json упал: {type(e).__name__}: {e}", exc_info=True)


def load_graph_stats():

    global graph_stats
    for path, label in ((GRAPH_STATS_PATH, "graph.json"), (GRAPH_STATS_BACKUP_PATH, "graph.json.bak")):
        if not os.path.exists(path):
            continue
        try:
            with open(path, 'r', encoding='utf-8') as f:
                raw = json.load(f)
        except (json.JSONDecodeError, OSError, UnicodeDecodeError) as e:
            logger.warning(f"[graph] Не удалось прочитать {label}: {type(e).__name__}: {e}")
            continue

        loaded = _coerce_graph_stats(raw)
        if not loaded and raw:
            logger.warning(f"⚠️ В {label} нет ни одной валидной серии "
                  f"(корень: {type(raw).__name__}), пропускаю файл.")
            continue

        dropped = _prune_graph_stats(loaded)
        graph_stats = loaded
        points = sum(len(series) for series in loaded.values())
        suffix = f", отброшено {dropped} устаревших точек" if dropped else ""
        logger.info(f"✅ Статистика для графика ({label}) загружена: {len(loaded)} досок, {points} точек{suffix}.")
        return

    logger.info("ℹ️ graph.json отсутствует или повреждён — статистика графика начнётся с нуля.")
    graph_stats = {}
async def graph_data_collector():
    """
    Фоновая задача, которая раз в час собирает статистику постов
    для каждой доски и сохраняет ее для построения графика.
    """
    await asyncio.sleep(60)
    while True:
        try:
            now = datetime.now(UTC)
            next_hour = (now + timedelta(hours=1)).replace(minute=0, second=5, microsecond=0)
            wait_seconds = (next_hour - now).total_seconds()
            await asyncio.sleep(wait_seconds)
            end_time = datetime.now(UTC)
            start_time = end_time - timedelta(hours=1)
            end_ts = end_time.timestamp()
            start_ts = start_time.timestamp()
            posts_per_hour = defaultdict(int)
            async with storage_lock:
                for post_data in reversed(messages_storage.values()):
                    timestamp = post_data.get('timestamp')
                    if hasattr(timestamp, 'timestamp'):
                        timestamp = timestamp.timestamp()
                    if not timestamp:
                        continue
                    if timestamp < start_ts:
                        break
                    if start_ts <= timestamp < end_ts:
                        board_id = post_data.get('board_id')
                        if board_id:
                            posts_per_hour[board_id] += 1
            timestamp_key = start_time.replace(minute=0, second=0, microsecond=0).isoformat()
            if not posts_per_hour:
                logger.info(f"📊 Сборщик статистики для графика: за час с {start_time.strftime('%H:%M')} не было активности.")
                continue
            for board_id, count in posts_per_hour.items():
                if count > 0:
                    graph_stats.setdefault(board_id, {})[timestamp_key] = count
            dropped = _prune_graph_stats(graph_stats)
            pruned_note = f", подрезано {dropped} точек старше {GRAPH_STATS_RETENTION_DAYS}д" if dropped else ""
            logger.info(f"📊 Статистика для графика собрана за {timestamp_key}. Активные доски: {list(posts_per_hour.keys())}{pruned_note}")

            # Сохраняем на диск в фоновом потоке.
            # graph_stats.copy() был поверхностным: поток сериализовал те же вложенные
            # dict'ы, которые здесь мутируются -> "dict changed size during iteration".
            # Снимаем полноценный снапшот и логируем провал записи, а не глотаем его.
            snapshot = {board_id: dict(series) for board_id, series in graph_stats.items()}
            save_future = asyncio.get_running_loop().run_in_executor(
                save_executor, _sync_save_graph_stats, snapshot
            )
            save_future.add_done_callback(_report_graph_save_result)
        except asyncio.CancelledError:
            logger.info("ℹ️ Сборщик статистики для графика остановлен.")
            break
        except Exception as e:
            logger.error(f"⛔ Ошибка в сборщике статистики для графика (graph_data_collector): {e}", exc_info=True)
            await asyncio.sleep(300)
def _prepare_graph_data(board_id: str, days: int):
    """Подготавливает DataFrame для графика, фильтруя и ресемплируя данные."""
    board_data_for_graph = graph_stats.get(board_id)
    if not board_data_for_graph:
        return None
    df = pd.DataFrame.from_dict(board_data_for_graph, orient='index', columns=['posts'])
    df.index = pd.to_datetime(df.index, utc=True)
    start_date_utc = pd.Timestamp.now(tz='UTC') - pd.Timedelta(days=days)
    df_filtered = df[df.index >= start_date_utc].copy()
    if df_filtered.empty:
        return None
    resample_period = '1h' if days <= 1 else '3h'
    end_date_utc = df_filtered.index.max()
    if pd.isna(end_date_utc):
        return None
    date_range_utc = pd.date_range(start=start_date_utc, end=end_date_utc, freq=resample_period, tz='UTC')
    df_resampled = df_filtered.resample(resample_period).sum().reindex(date_range_utc).fillna(0)
    if df_resampled.empty or df_resampled['posts'].max() == 0:
        return None
    return df_resampled


def _setup_graph_axes(ax, days: int, df_resampled, board_id: str):
    """Настраивает оси, сетку и подписи графика."""
    board_name = BOARD_CONFIG.get(board_id, {}).get('name', board_id)
    period_str = f"{days} day(s)" if board_id == 'int' else f"{days} дн."
    ax.set_title(f"Активность доски {board_name} за {period_str}", fontsize=16, color='white', pad=20)

    max_val = df_resampled['posts'].max()
    if max_val < 5:
        nice_max = 5
    else:
        power = 10 ** math.floor(math.log10(max_val)) if max_val > 0 else 1
        nice_max = math.ceil(max_val / power) * power
        if nice_max * 0.8 > max_val:
             nice_max = math.ceil(max_val / (power/2)) * (power/2)
    ax.set_ylim(0, nice_max * 1.05)
    ax.set_yticks(np.linspace(0, nice_max, 6, dtype=int))
    ax.set_ylabel("Постов в час" if days <= 1 else "Постов за 3 часа", fontsize=12, color='white')

    MSK = timezone(timedelta(hours=3))
    if days <= 1:
        ax.xaxis.set_major_locator(mdates.HourLocator(interval=4, tz=MSK))
        ax.xaxis.set_major_formatter(mdates.DateFormatter('%H', tz=MSK))
        ax.xaxis.set_minor_locator(mdates.HourLocator(interval=1, tz=MSK))
        ax.set_xlabel("Время (МСК)", fontsize=12, color='white')
    else:
        day_interval = max(1, days // 7)
        ax.xaxis.set_major_locator(mdates.DayLocator(interval=day_interval, tz=MSK))
        ax.xaxis.set_major_formatter(mdates.DateFormatter('%d %b', tz=MSK))
        ax.xaxis.set_minor_locator(mdates.HourLocator(interval=3, tz=MSK))

    ax.set_facecolor('#0d1117')
    ax.grid(True, which='major', linestyle='--', linewidth=0.4, color='#30363d')
    ax.grid(True, which='minor', linestyle=':', linewidth=0.2, color='#21262d')
    for spine in ax.spines.values():
        spine.set_color('#30363d')
    ax.tick_params(axis='x', which='major', labelsize=10, length=6, width=1.5, colors='white', rotation=0, ha="center")
    ax.tick_params(axis='y', which='major', labelsize=10, colors='white')
    ax.tick_params(axis='both', which='minor', length=4, width=0.5)


def generate_statistics_graph(board_id: str, days: int) -> bytes | None:
    """
    Генерирует изображение графика статистики постов для указанной доски за заданный период.
    Возвращает изображение в виде байтов или None в случае ошибки.
    """
    if not GRAPH_LIBS_AVAILABLE:
        print("⛔ Зависимости для графиков (pandas, matplotlib) не установлены.")
        return None
    # Крутится в дефолтном пуле потоков (до 32 воркеров), а plt.style.use ниже
    # заменяет ГЛОБАЛЬНЫЕ rcParams. Без замка два параллельных /graph рисовали
    # друг другу чужую тему. См. common/chart_lock.py.
    try:
        with matplotlib_guard():
            return _generate_statistics_graph_locked(board_id, days)
    except ChartLockTimeout as e:
        logger.warning(f"⛔ График не построен: {e}")
        return None


def _generate_statistics_graph_locked(board_id: str, days: int) -> bytes | None:
    plt.close('all')
    try:
        df_resampled = _prepare_graph_data(board_id, days)
        if df_resampled is None:
            return None

        plt.style.use('dark_background')
        num_points = len(df_resampled)
        width = max(10, min(20, num_points * 0.3))
        height = 6 if width <= 12 else 7

        fig, ax = plt.subplots(figsize=(width, height), dpi=110)
        line_color = '#00ffff'
        ax.plot(df_resampled.index, df_resampled['posts'], color=line_color, linewidth=2.5, marker='o', markersize=4, markeredgecolor='white', markerfacecolor=line_color, zorder=10)
        ax.fill_between(df_resampled.index, df_resampled['posts'], color=line_color, alpha=0.1, zorder=5)

        _setup_graph_axes(ax, days, df_resampled, board_id)

        fig.patch.set_facecolor('#0d1117')
        fig.tight_layout(pad=1.5)

        buf = io.BytesIO()
        fig.savefig(buf, format='png', facecolor=fig.get_facecolor(), edgecolor='none')
        buf.seek(0)

        plt.close(fig)
        plt.close('all') # Закрываем вообще всё
        fig = None
        ax = None
        gc.collect()

        return buf.getvalue()
    except Exception as e:
        import traceback
        print(f"⛔ Ошибка при генерации графика: {e}\n{traceback.format_exc()}")
        if 'fig' in locals() and 'fig' in vars() and plt.fignum_exists(fig.number):
            plt.close(fig)
        return None
