@dp.message(Command("dice", "roll100", "d100", "кости", ignore_case=True, ignore_mention=True))
async def cmd_dice(message: types.Message, board_id: str | None, stream: str = 'ru'):
    try: spawn_task(delete_message_after_delay(message, 5))
    except Exception as e: runtime_logger.warning(f"Failed to spawn delete_message task: {e}")

    if not board_id: return
    user_id = message.from_user.id
    lang = stream if ENABLE_MULTILANG else ('en' if board_id == 'int' else 'ru')

    args = (message.text or message.caption or "").split()
    bet = None
    new_bal = None
    outcome_text = ""
    result = random.randint(1, 100)

    if len(args) > 1:
        arg_val = args[1].lower().strip().lstrip('+')
        err_text = None
        db = await get_pool()
        async with db_lock:
            async with db.execute("SELECT SUM(balance) FROM Users WHERE user_id = ?", (user_id,)) as c:
                row = await c.fetchone()
                balance = row[0] if row and row[0] is not None else 0

            bet = None
            if arg_val in ["all", "вабанк", "ва-банк", "всё", "все"]:
                bet = int(balance)
            elif arg_val.isdigit():
                bet = int(arg_val)
            else:
                try:
                    f_val = float(arg_val)
                    if not math.isnan(f_val) and not math.isinf(f_val) and f_val > 0:
                        bet = int(f_val)
                except (ValueError, OverflowError):
                    bet = None

            if bet is None or bet <= 0:
                err_text = "❌ Неверный формат ставки! Укажи число, например: <code>/dice 50</code> или <code>/dice all</code>."
            elif bet < 10:
                err_text = "❌ Минимальная ставка для игры в кости: 10 ₪."
            elif bet > balance:
                err_text = f"❌ Недостаточно шекелей! Твой баланс: <code>{int(balance)} ₪</code>."
            elif bet > 10000:
                err_text = "❌ Максимальная ставка за один бросок: 10 000 ₪."
            else:
                # Anti-script Cooldown
                is_ok, rem = casino_engine.check_casino_cooldown(user_id)
                if not is_ok:
                    err_text = f"⏳ <b>Кости еще горячие!</b> Подожди <code>{rem}с</code> перед следующим броском."
                else:
                    # VIP Table Rake
                    rake, active_bet = casino_engine.calculate_vip_table_rake(bet)
                    if rake > 0:
                        await add_to_abu_fund(db, rake)

                    # Raid Chance
                    is_raid, raid_notice = check_casino_raid_trigger(balance=int(balance), bet=bet)
                    if is_raid and raid_notice:
                        await deduct_user_global_balance(db, user_id, board_id, bet)
                        await add_to_abu_fund(db, bet)
                        await record_user_transaction(db, user_id, -bet, 'casino', 'Облава СОБР в костях')
                        new_bal = await get_user_global_balance(db, user_id)
                        outcome_text = f"🚨 <b>ОБЛАВА В ИГОРНОМ КЛУБЕ!</b>\n{raid_notice['reason']}\n\n<i>{raid_notice['quote']}</i>\n\n📉 Ставка <code>-{bet} ₪</code> изъята в Казну Абу."
                        casino_engine.record_win_streak(user_id, False)
                    else:
                        # Dynamic Anti-Streak / High-Roller Tilt
                        streak = casino_engine.get_win_streak(user_id)
                        win_threshold = 60 if (streak >= 3 or balance > 100_000) else 55

                        if result == 100:
                            win = bet * 3
                            tax_amt, actual_win = calculate_win_tax(win)
                            if tax_amt > 0: await add_to_abu_fund(db, int(tax_amt))
                            await add_user_global_balance(db, user_id, board_id, actual_win)
                            await record_user_transaction(db, user_id, actual_win, 'casino', f'Джекпот в кости (100/100)')
                            casino_engine.record_win_streak(user_id, True)
                            outcome_text = f"👑 <b>ДЖЕКПОТ 100/100!</b>\n🔥 Множитель x4! Чистый выигрыш: <code>+{actual_win} ₪</code>"
                        elif result >= win_threshold:
                            win = bet
                            tax_amt, actual_win = calculate_win_tax(win)
                            if tax_amt > 0: await add_to_abu_fund(db, int(tax_amt))
                            await add_user_global_balance(db, user_id, board_id, actual_win)
                            await record_user_transaction(db, user_id, actual_win, 'casino', f'Победа в кости ({result}/100)')
                            casino_engine.record_win_streak(user_id, True)
                            outcome_text = f"🎉 <b>ПОБЕДА!</b> Выпало {result} (≥{win_threshold}).\n💰 Ты поднял: <code>+{actual_win} ₪</code>"
                        else:
                            await deduct_user_global_balance(db, user_id, board_id, bet)
                            await add_to_abu_fund(db, bet)
                            await record_user_transaction(db, user_id, -bet, 'casino', f'Слив в костях ({result}/100)')
                            casino_engine.record_win_streak(user_id, False)
                            outcome_text = f"💀 <b>ПРОИГРЫШ!</b> Выпало {result} (&lt;{win_threshold}).\n📉 Ты слил ставку: <code>-{bet} ₪</code>"

                        new_bal = await get_user_global_balance(db, user_id)

        if err_text:
            await message.answer(err_text)
            return

        caption = (
            f"🎲 <b>ПОДПОЛЬНЫЕ КОСТИ ТГАЧА</b>\n"
            f"Ставка: <code>{bet} ₪</code> | Результат ролла: <b>{result}/100</b>\n\n"
            f"{outcome_text}\n\n"
            f"💳 Твой новый баланс: <code>{int(new_bal)} ₪</code>"
        )
    else:
        if lang == 'en':
            roll_text = f"🎲 Rolled: {result}"
        elif lang == 'jp':
            roll_text = f"🎲 出目: {result}"
        else:
            roll_text = f"🎲 Нароллил: {result}"
        caption = f"🎰 <b>РЕЗУЛЬТАТ РОЛЛА:</b>\n\n{roll_text}\n\n<i>💡 Совет: Сыграй на шекели — <code>/dice 50</code> или <code>/dice all</code></i>"

    try:
        from banner_manager import send_banner_message
        sent_msg = await send_banner_message(
            bot=message.bot,
            chat_id=message.chat.id,
            caption=caption,
            category="roulette",
            parse_mode="HTML"
        )
        if sent_msg:
            spawn_task(delete_message_after_delay(sent_msg, 60))
        await message.delete()
    except (TelegramForbiddenError, TelegramBadRequest):
        pass


@dp.message(Command("quote", "цитата", "пост", "random_post"))
async def cmd_quote(message: types.Message, board_id: str | None, stream: str = 'ru'):
    if not board_id: return
    import html
    db = await get_pool()
    lang = stream if ENABLE_MULTILANG else ('en' if board_id == 'int' else 'ru')

    async with db.execute(
        """SELECT post_num, content, author_id
           FROM Posts
           WHERE board_id = ? AND length(content) > 20 AND is_shadow = 0
           ORDER BY RANDOM() LIMIT 1""",
        (board_id,)
    ) as c:
        row = await c.fetchone()

    if not row:
        no_post = "No posts found." if lang == 'en' else "Нет постов на борде."
        await message.answer(no_post)
        return

    post_num, content, author_id = row
    excerpt = content[:400].strip()
    if len(content) > 400:
        excerpt += "…"

    anon_id_val = get_anon_id(author_id, 'en' if lang == 'en' else 'ru')
    anon_tag = f"Anon [{anon_id_val}]" if lang == 'en' else f"Анон [{anon_id_val}]"
    escaped = html.escape(excerpt)
    header = "🎲 <b>Random post:</b>" if lang == 'en' else "🎲 <b>Случайный пост:</b>"

    text = (
        f"{header}\n"
        f"<blockquote>{escaped}</blockquote>\n"
        f"<i>— {anon_tag} | #{post_num} | /{board_id}/</i>"
    )
    try:
        await message.answer(text, parse_mode="HTML")
        await message.delete()
    except Exception:
        pass


@dp.message(Command("addmoney"))
async def cmd_add_money_admin(message: Message, board_id: str | None):
    if not board_id or not is_admin(message.from_user.id, board_id): return
    try: await message.delete()
    except Exception: pass
    
    args = (message.text or message.caption or "").split()
    if len(args) < 3:
        await message.answer("Юзай: /addmoney &lt;ID&gt; &lt;сумма&gt;")
        return
        
    try:
        target_id, amount = int(args[1]), int(args[2])
        async with db_lock:
            db = await get_pool()
            # 1. Гарантируем, что запись на ТЕКУЩЕЙ доске существует
            await db.execute("INSERT OR IGNORE INTO Users (user_id, board_id) VALUES (?, ?)", (target_id, board_id))
            # 2. Начисляем деньги ТОЛЬКО в эту запись (избегаем умножения)
            await db.execute("UPDATE Users SET balance = balance + ? WHERE user_id = ? AND board_id = ?", (amount, target_id, board_id))
            await db.commit()
        
        await message.answer(f"✅ Нарисовано {amount} рублей для юзера {target_id}. Баланс пополнен (корзина /{board_id}/).")
        try:
            await message.bot.send_message(target_id, f"🎁 <b>Администрация начислила вам бонус: {amount} RUB! Кошелек - /wallet </b>", parse_mode="HTML")
        except Exception:
            pass
    except Exception as e:
        await message.answer(f"Ошибка: {e}", parse_mode=None)
