# Окна хранения для per-user трекеров (секунды).
# Каждое НАМНОГО больше функционального окна соответствующей проверки,
# поэтому подрезка физически не может изменить поведение антиспама.
STALE_TRACKER_TTL = 3600          # для окон в 0.5-60 сек
STALE_DAILY_TRACKER_TTL = 172800  # для суточных лимитов (окно 86400)


def _prune_by_timestamp(mapping: dict, now: float, ttl: float) -> int:
    """Удаляет ключи из {key: timestamp}, чей timestamp старше ttl."""
    stale = [k for k, ts in mapping.items() if not isinstance(ts, (int, float)) or now - ts > ttl]
    for k in stale:
        mapping.pop(k, None)
    return len(stale)


def _prune_timestamp_sequences(mapping: dict, now: float, ttl: float) -> int:
    """
    Удаляет ключи из {key: [ts, ...]} / {key: deque([...])}, где нет ни одной
    свежей отметки. Элементом может быть как float, так и кортеж (ts, ...).
    """
    def _newest(seq) -> float:
        newest = 0.0
        for item in seq:
            ts = item[0] if isinstance(item, tuple) and item else item
            if isinstance(ts, (int, float)) and ts > newest:
                newest = float(ts)
        return newest

    stale = []
    for key, seq in mapping.items():
        try:
            if not seq or now - _newest(seq) > ttl:
                stale.append(key)
        except TypeError:
            stale.append(key)
    for k in stale:
        mapping.pop(k, None)
    return len(stale)


def _prune_idle_locks(locks: dict) -> int:
    """
    Удаляет незанятые asyncio.Lock.

    Безопасно: неконкурентный `async with lock` не отдаёт управление event loop
    (Lock.acquire возвращается синхронно, если lock свободен), поэтому у
    свободного лока без waiters не может быть таска "в процессе захвата".
    Занятые и ожидаемые локи не трогаем.
    """
    stale = []
    for key, lock in locks.items():
        try:
            if not lock.locked() and not getattr(lock, "_waiters", None):
                stale.append(key)
        except Exception:
            continue
    for k in stale:
        locks.pop(k, None)
    return len(stale)


def _prune_contextual_reply_tracker(now: float, ttl: float) -> int:
    """Чистит {(board, user): {'last','window_start','count'}} по самой свежей отметке."""
    stale = []
    for key, item in contextual_reply_tracker.items():
        if not isinstance(item, dict):
            stale.append(key)
            continue
        newest = max(
            float(item.get("last") or 0.0),
            float(item.get("window_start") or 0.0),
        )
        if now - newest > ttl:
            stale.append(key)
    for k in stale:
        contextual_reply_tracker.pop(k, None)
    return len(stale)


def _prune_shadow_fake_counters() -> int:
    """
    Чистит {(board, user): fake_post_num} для юзеров, снятых с шэдоу-мута.

    Времени в записи нет, поэтому единственный корректный критерий —
    пользователь больше не в shadow_mutes своей доски.
    """
    stale = []
    for key in shadow_fake_post_counters:
        if not (isinstance(key, tuple) and len(key) == 2):
            stale.append(key)
            continue
        board_id, user_id = key
        if board_id not in board_data:
            stale.append(key)
            continue
        if user_id not in board_data[board_id].get('shadow_mutes', {}):
            stale.append(key)
    for k in stale:
        shadow_fake_post_counters.pop(k, None)
    return len(stale)


def _sweep_stale_runtime_maps() -> dict[str, int]:
    """
    Подрезает per-user словари, которые росли без ограничений.

    Все эти карты попадают в телеметрию (_collect_global_maps_snapshot), но
    раньше их никто не чистил: на боте с большим оборотом пользователей они
    держали десятки тысяч мёртвых записей до самого memory_restarter.
    Синхронная функция без await — прерваться посреди подрезки нельзя.
    """
    now = time.time()
    removed: dict[str, int] = {}

    def _note(name: str, count: int) -> None:
        if count:
            removed[name] = count

    for name, mapping in (
        ("user_last_thread_action", user_last_thread_action),
        ("reaction_ratelimit", reaction_ratelimit),
        ("last_poll_creation_time", last_poll_creation_time),
        ("last_poll_vote_time", last_poll_vote_time),
        ("user_hourly_image_reset", user_hourly_image_reset),
    ):
        _note(name, _prune_by_timestamp(mapping, now, STALE_TRACKER_TTL))

    # Счётчик картинок живёт в паре с меткой сброса — выкидываем осиротевшие.
    orphan_counts = [uid for uid in user_hourly_image_count if uid not in user_hourly_image_reset]
    for uid in orphan_counts:
        user_hourly_image_count.pop(uid, None)
    _note("user_hourly_image_count", len(orphan_counts))

    for name, mapping in (
        ("unknown_command_tracker", unknown_command_tracker),
        ("author_reaction_notify_tracker", author_reaction_notify_tracker),
        # держит тексты сообщений (ts, board, content) -> самый жирный из трекеров
        ("cross_board_spam_tracker", cross_board_spam_tracker),
    ):
        _note(name, _prune_timestamp_sequences(mapping, now, STALE_TRACKER_TTL))

    _note("contextual_reply_tracker",
          _prune_contextual_reply_tracker(now, STALE_DAILY_TRACKER_TTL))
    _note("shadow_fake_post_counters", _prune_shadow_fake_counters())

    for name, locks in (("generate_locks", generate_locks), ("user_spam_locks", user_spam_locks)):
        _note(name, _prune_idle_locks(locks))

    # Combat & duel cooldowns
    combat_expired = [uid for uid, ts in list(shared_state._GLOBAL_COMBAT_COOLDOWNS.items()) if ts <= now]
    for uid in combat_expired:
        shared_state._GLOBAL_COMBAT_COOLDOWNS.pop(uid, None)
    _note("_GLOBAL_COMBAT_COOLDOWNS", len(combat_expired))

    victim_rob_expired = [uid for uid, ts in list(shared_state._VICTIM_ROB_COOLDOWNS.items()) if ts <= now]
    for uid in victim_rob_expired:
        shared_state._VICTIM_ROB_COOLDOWNS.pop(uid, None)
    _note("_VICTIM_ROB_COOLDOWNS", len(victim_rob_expired))

    duel_expired = [uid for uid, ts in list(shared_state._duel_cooldowns.items()) if now - ts > 3600]
    for uid in duel_expired:
        shared_state._duel_cooldowns.pop(uid, None)
    _note("_duel_cooldowns", len(duel_expired))

    history_expired = []
    for uid, history in list(shared_state._ATTACKER_TARGET_HISTORY.items()):
        valid = [(ts, tid) for ts, tid in history if now - ts <= shared_state._ATTACK_WINDOW_SEC]
        if valid:
            shared_state._ATTACKER_TARGET_HISTORY[uid] = valid
        else:
            history_expired.append(uid)
    for uid in history_expired:
        shared_state._ATTACKER_TARGET_HISTORY.pop(uid, None)
    _note("_ATTACKER_TARGET_HISTORY", len(history_expired))

    for item_type, attackers in list(shared_state._ACTIVE_AUTHOR_ATTACKS.items()):
        empty_attackers = []
        for attacker_id, victims in list(attackers.items()):
            active_victims = {tgt: exp for tgt, exp in victims.items() if exp > now}
            if active_victims:
                attackers[attacker_id] = active_victims
            else:
                empty_attackers.append(attacker_id)
        for aid in empty_attackers:
            attackers.pop(aid, None)

    # Per-board user tracking maps in board_data
    board_cleanups = 0
    for b_id, b_dict in board_data.items():
        st = b_dict.get('spam_tracker')
        if isinstance(st, dict):
            empty_st = [u for u, ts_list in list(st.items()) if not ts_list or (isinstance(ts_list, list) and max(ts_list or [0]) < now - 3600)]
            for u in empty_st:
                st.pop(u, None)
            board_cleanups += len(empty_st)

        lrt = b_dict.get('last_roll_time')
        if isinstance(lrt, dict):
            expired_roll = [u for u, ts in list(lrt.items()) if now - ts > 86400]
            for u in expired_roll:
                lrt.pop(u, None)
            board_cleanups += len(expired_roll)

        lic = b_dict.get('last_info_command_time')
        if isinstance(lic, dict):
            expired_info = [u for u, ts in list(lic.items()) if now - ts > 3600]
            for u in expired_info:
                lic.pop(u, None)
            board_cleanups += len(expired_info)
    _note("board_data_stale_entries", board_cleanups)

    return removed


async def auto_memory_cleaner():
    """
    Фоновая задача для периодической очистки закэшированных данных в глобальных словарях,
    чтобы предотвратить утечки памяти.
    """
    while True:
        try:
            await asyncio.sleep(3600)  # Запускаем раз в час

            # 1. Очистка stream_cache
            cache_size = len(stream_cache)
            stream_cache.clear()

            # 2. Очистка завершенных pending_edit_tasks
            done_tasks = [k for k, t in pending_edit_tasks.items() if t.done()]
            for k in done_tasks:
                pending_edit_tasks.pop(k, None)

            # 3. Подрезка per-user трекеров, которые росли безгранично
            removed = _sweep_stale_runtime_maps()

            # 4. Фоновый WAL checkpointing для сжатия базы
            try:
                db_clean = await get_pool()
                async with db_lock:
                    await db_clean.execute("PRAGMA wal_checkpoint(PASSIVE);")
            except Exception:
                pass

            # 5. Очистка временных файлов диска старше 24 часов
            try:
                import glob
                now_disk = time.time()
                for p in glob.glob("temp_*.*") + glob.glob("data/temp/*.*"):
                    try:
                        if os.path.isfile(p) and now_disk - os.path.getmtime(p) > 86400:
                            os.remove(p)
                    except Exception:
                        pass
            except Exception:
                pass


            total_stale = sum(removed.values())
            if done_tasks or cache_size or total_stale:
                detail = ", ".join(f"{name}={count}" for name, count in
                                   sorted(removed.items(), key=lambda kv: kv[1], reverse=True))
                print(f"🚮 [Memory Cleaner] Мертвых тасок: {len(done_tasks)}, кэш стримов: {cache_size}, "
                      f"устаревших записей: {total_stale}"
                      + (f" ({detail})" if detail else ""))

        except asyncio.CancelledError:
            break
        except Exception as e:
            print(f"Ошибка в auto_memory_cleaner: {type(e).__name__}: {e}")
            runtime_logger.exception("auto_memory_cleaner_failed")
            await asyncio.sleep(60)

async def runtime_telemetry_task():

    await asyncio.sleep(60)
    previous_private_mb = None
    while True:
        try:
            await _refresh_db_file_snapshot_cache()
            snapshot = _collect_runtime_snapshot()
            memory = snapshot.get("memory", {})
            queues = snapshot.get("queues", {})
            maps = snapshot.get("maps", {})
            private_mb = memory.get("private_mb")
            private_delta = None
            if isinstance(private_mb, (int, float)) and isinstance(previous_private_mb, (int, float)):
                private_delta = round(private_mb - previous_private_mb, 2)
            if isinstance(private_mb, (int, float)):
                previous_private_mb = private_mb
            runtime_logger.debug(
                "runtime_snapshot %s",
                json.dumps(snapshot, ensure_ascii=False, separators=(",", ":"))
            )
            warnings = []
            if isinstance(private_mb, (int, float)) and private_mb > MEMORY_LIMIT_GB * 1024 * 0.75:
                warnings.append(f"private_mb={private_mb}")
            if queues.get("total", 0) > TELEMETRY_WARN_QUEUE_TOTAL:
                warnings.append(f"queue_total={queues.get('total')}")
            if maps.get("pending_edit_done", 0) > TELEMETRY_WARN_DONE_EDIT_TASKS:
                warnings.append(f"done_edit_tasks={maps.get('pending_edit_done')}")
            if maps.get("current_media_groups", 0) > TELEMETRY_WARN_MEDIA_GROUPS:
                warnings.append(f"media_groups={maps.get('current_media_groups')}")
            top_queue = ", ".join(f"{board}:{size}" for board, size in queues.get("top", [])) or "empty"
            line = (
                f"[runtime] private={private_mb}MB "
                f"delta={private_delta}MB queues={queues.get('total', 0)} top={top_queue} "
                f"maps=({maps.get('messages_storage')}/{maps.get('post_to_messages')}/{maps.get('message_to_post')}) "
                f"wal={snapshot.get('db_files', {}).get('wal_mb')}MB"
            )
            if warnings:
                runtime_logger.debug("runtime_warning %s %s", ",".join(warnings), line)
                print(line)
            else:
                print(line)
        except Exception as e:
            runtime_logger.exception("runtime_telemetry_failed")
            print(f"⚠️ runtime_telemetry_task error: {e}")
        await asyncio.sleep(TELEMETRY_INTERVAL_SEC)
async def weekly_active_refresh_task():
    if not PRIORITY_DELIVERY_ENABLED:
        return
    while True:
        try:

            refreshed_at = time.time()
            counts = {}
            for board_id in BOARDS:
                users = await get_weekly_active_users(board_id, WEEKLY_ACTIVE_DAYS)
                weekly_active_users[board_id] = users
                weekly_active_updated_at[board_id] = refreshed_at
                counts[board_id] = len(users)
            total = sum(counts.values())
            top = sorted(counts.items(), key=lambda item: item[1], reverse=True)[:5]
            runtime_logger.debug(
                "weekly_active_refresh %s",
                json.dumps(
                    {
                        "days": WEEKLY_ACTIVE_DAYS,
                        "total": total,
                        "by_board": counts,
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
            )
            top_text = ", ".join(f"{board}:{count}" for board, count in top)
            print(f"[priority] weekly active {WEEKLY_ACTIVE_DAYS}d: total={total} top={top_text}")
        except Exception:
            runtime_logger.exception("weekly_active_refresh_failed")
        await asyncio.sleep(WEEKLY_ACTIVE_REFRESH_SECONDS)
