@dp.callback_query(F.data.startswith("loli_explain:"))
async def cb_loli_explain(callback: types.CallbackQuery, board_id: str | None):
    bust_id = callback.data.split(":", 1)[1]
    bust = LOLI_BUST_STATE.get(bust_id)
    if not bust:
        await callback.answer("Дело уже закрыто и сдано в архив! Объяснительную писать поздно.", show_alert=True)
        return
    if callback.from_user.id != bust["user_id"]:
        await callback.answer("Это не твоё уголовное дело! Не суй нос в чужие протоколы.", show_alert=True)
        return

    LOLI_BUST_STATE.pop(bust_id, None)
    user_id = bust["user_id"]
    target_board = bust["board_id"] or board_id or "b"
    actual_fine = bust["actual_fine"]
    chosen_text = random.choice(LOLI_EXPLANATION_TEXTS)
    db = await get_pool()

    is_mercy = random.random() < 0.25

    if is_mercy:
        refund = round(actual_fine * 0.5, 2)
        if refund > 0:
            new_bal = await add_user_global_balance(db, user_id, target_board, refund)
            await deduct_from_abu_fund(db, refund, reason=f"Возврат 50% штрафа по объяснительной user={user_id}")
            await record_user_transaction(db, user_id, refund, "police", "Возврат 50% штрафа по объяснительной")
        else:
            new_bal = await get_user_global_balance(db, user_id)

        result_text = (
            f"📝 <b>ОБЪЯСНИТЕЛЬНАЯ ПРИНЯТА К СВЕДЕНИЮ</b>\n\n"
            f"<i>«{chosen_text}»</i>\n\n"
            f"🥹 <b>РЕШЕНИЕ МАЙОРА:</b>\n"
            f"Товарищ майор вытер скупую мужскую слезу, глубоко вздохнул и постановил:\n"
            f"<i>«Чёрт с тобой, анон. Видно, что дурак, но не со зла. Половину штрафа возвращаю, но чтоб больше на глаза не попадался!»</i>\n\n"
            f"💸 Возвращено на баланс: <code>+{refund:,.0f} ₪</code>\n"
            f"💰 Твой баланс: <code>{new_bal:,.2f} ₪</code>"
        )
    else:
        extra_fine = 20.0
        cur_bal = await get_user_global_balance(db, user_id)
        act_extra = min(extra_fine, max(0.0, cur_bal))
        if act_extra > 0:
            _, new_bal = await deduct_user_global_balance(db, user_id, target_board, act_extra)
            await add_to_abu_fund(db, act_extra, donor_id=user_id, reason="Штраф за дачу ложных показаний майору")
            await record_user_transaction(db, user_id, -act_extra, "police", "Штраф за ложные показания")
        else:
            new_bal = 0.0

        extra_str = f"-{act_extra:,.0f} ₪" if act_extra > 0 else "0 ₪ (с голодранца взять нечего)"
        result_text = (
            f"📝 <b>ОБЪЯСНИТЕЛЬНАЯ ОТКЛОНЕНА</b>\n\n"
            f"<i>«{chosen_text}»</i>\n\n"
            f"🚨 <b>РЕШЕНИЕ МАЙОРА:</b>\n"
            f"Товарищ майор скомкал листок и со всей дури хлопнул папкой по столу:\n"
            f"<i>«Ты кого наебать пытаешься, сыч?! За попытку дачи заведомо ложных показаний накидываю ещё 20 ₪ сверху в доход государства!»</i>\n\n"
            f"💸 Дополнительный штраф: <code>{extra_str}</code> в Фонд Абу.\n"
            f"💰 Твой баланс: <code>{new_bal:,.2f} ₪</code>"
        )

    try:
        await callback.message.edit_text(result_text, parse_mode="HTML")
    except Exception:
        await callback.message.answer(result_text, parse_mode="HTML")
    await callback.answer()

# --- ДОПРОС В ОТДЕЛЕ К ---
USER_DOPROS_COOLDOWN: dict[int, float] = {}
DOPROS_COOLDOWN_SEC: float = 1800.0
ACTIVE_DOPROS: dict[str, dict] = {}

@dp.message(Command("dopros", "допрос", ignore_case=True, ignore_mention=True))
async def cmd_dopros(message: types.Message, board_id: str | None):
    if not board_id: return
    user_id = message.from_user.id
    now = time.time()

    if not message.reply_to_message:
        await message.answer("⚠️ Сделай <b>Reply (ответ)</b> на пост подозреваемого анона с командой <code>/dopros</code>!", parse_mode="HTML")
        return

    last_time = USER_DOPROS_COOLDOWN.get(user_id, 0.0)
    if now - last_time < DOPROS_COOLDOWN_SEC:
        rem_min = int((DOPROS_COOLDOWN_SEC - (now - last_time)) // 60) + 1
        await message.answer(f"⏳ Товарищ майор сейчас занят заполнением протоколов. Следующий вызов на допрос через {rem_min} мин.")
        return

    target_id = await get_author_id_by_reply(message)
    if not target_id and message.reply_to_message.from_user and not message.reply_to_message.from_user.is_bot:
        target_id = message.reply_to_message.from_user.id

    if not target_id or target_id == 0:
        await message.answer("⚠️ Не удалось определить подозреваемого по ответу на сообщение (возможно, это системный пост бота).")
        return

    if target_id == user_id:
        await message.answer("🤦‍♂️ Ты не можешь вызвать на допрос самого себя! Сделай Reply на пост подозреваемого.")
        return

    if is_admin(target_id, board_id):
        await message.answer(
            "👮‍♂️ <b>ОТМЕНА ОПЕРАЦИИ!</b>\n\n"
            "Товарищ майор заглянул в личное дело подозреваемого, увидел генеральские погоны Администратора, вытянулся в струнку, извинился и поспешно сжёг повестку в пепельнице.",
            parse_mode="HTML"
        )
        return

    USER_DOPROS_COOLDOWN[user_id] = now
    dopros_id = secrets.token_hex(4)
    protocol_num = random.randint(100, 999)
    ACTIVE_DOPROS[dopros_id] = {
        "target_id": target_id,
        "initiator_id": user_id,
        "board_id": board_id,
        "created_at": now,
    }

    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="💸 Дать взятку (50 ₪)", callback_data=f"dopros_bribe:{dopros_id}")],
        [InlineKeyboardButton(text="🤐 51-я статья (молчать)", callback_data=f"dopros_art51:{dopros_id}")],
        [InlineKeyboardButton(text="👉 Сдать соседа по борде", callback_data=f"dopros_snitch:{dopros_id}")]
    ])

    target_anon = f"Анон [{get_anon_id(target_id)}]"
    text = (
        f"📋 <b>ПОВЕСТКА НА ДОПРОС В ОТДЕЛ «К» №{protocol_num}</b>\n\n"
        f"Гражданин <b>{target_anon}</b> вызван в кабинет №404 по подозрению в антисоветском шизопостинге, хранении запрещённых мемов и неуважении к товарищу майору!\n\n"
        f"<i>Следователь положил на стол чистый протокол и тяжёлый взгляд. Твоя линия защиты:</i>"
    )

    try:
        await message.bot.send_message(
            chat_id=message.chat.id,
            text=text,
            reply_to_message_id=message.reply_to_message.message_id,
            reply_markup=kb,
            parse_mode="HTML"
        )
    except Exception:
        await message.answer(text, parse_mode="HTML", reply_markup=kb)

    try:
        await message.bot.send_message(
            chat_id=target_id,
            text=(
                f"🚨 <b>ВАС ВЫЗВАЛИ НА ДОПРОС В ОТДЕЛ «К»!</b>\n\n"
                f"На борде <b>/{board_id}/</b> на вас поступило заявление.\n\n"
                f"{text}"
            ),
            reply_markup=kb,
            parse_mode="HTML"
        )
    except Exception:
        pass

@dp.callback_query(F.data.startswith("dopros_"))
async def cb_dopros_action(callback: types.CallbackQuery, board_id: str | None):
    parts = callback.data.split(":")
    if len(parts) != 2: return
    action, dopros_id = parts[0], parts[1]
    dopros = ACTIVE_DOPROS.get(dopros_id)
    if not dopros:
        await callback.answer("Протокол допроса уже сдан в архив!", show_alert=True)
        return
    if callback.from_user.id != dopros["target_id"]:
        await callback.answer("Это не твой допрос, гражданин! Проходи, не задерживай следствие.", show_alert=True)
        return

    ACTIVE_DOPROS.pop(dopros_id, None)
    target_id = dopros["target_id"]
    target_board = dopros["board_id"] or board_id or "b"
    db = await get_pool()

    if action == "dopros_bribe":
        b_amount = 50.0
        cur_bal = await get_user_global_balance(db, target_id)
        if cur_bal < b_amount:
            await callback.answer("❌ Взятка отклонена! У тебя даже 50 ₪ нет на кармане!", show_alert=True)
            text = (
                "🔒 <b>ВЗЯТКА НЕ ПРОШЛА!</b>\n\n"
                "Следователь брезгливо посмотрел на пустые карманы анона:\n"
                "<i>«С голодранца и взять нечего. Пиши явку с повинной!»</i>\n\n"
                "Анон отправлен в КПЗ на 5 минут за попытку подкупа при отсутствии денег!"
            )
            await update_shadow_mute(user_id=target_id, board_id=target_board, duration_seconds=300, reason="dopros_failed_bribe")
        else:
            await deduct_user_global_balance(db, target_id, target_board, b_amount)
            await add_to_abu_fund(db, b_amount, donor_id=target_id, reason="Взятка на допросе в Отделе К")
            await record_user_transaction(db, target_id, -b_amount, "police", "Взятка следователю /dopros")
            text = (
                "💸 <b>ДЕЛО ЗАКРЫТО!</b>\n\n"
                "Конверт с <b>50 ₪</b> незаметно перекочевал в ящик стола следователя.\n"
                "<i>«По результатам проверки состав преступления не обнаружен. Протокол случайно попал в шредер. Свободен, гражданин!»</i>"
            )
    elif action == "dopros_art51":
        if random.random() < 0.50:
            text = (
                "🤐 <b>51-Я СТАТЬЯ СРАБОТАЛА!</b>\n\n"
                "Анон сидел с каменным лицом и молчал как партизан.\n"
                "Следователь вздохнул, не нашёл прямых улик и с досадой постановил:\n"
                "<i>«Умный больно? Ладно, гуляй пока. Но ты у нас на карандаше!»</i>"
            )
        else:
            await update_shadow_mute(user_id=target_id, board_id=target_board, duration_seconds=300, reason="dopros_art51_contempt")
            text = (
                "🚨 <b>НЕУВАЖЕНИЕ К СЛЕДСТВИЮ!</b>\n\n"
                "Анон решил поиграть в молчанку, но следователь оказался старой закалки.\n"
                "<i>«Молчишь? Значит, виновен! 5 минут в КПЗ (шедоумут) освежат твою память!»</i>"
            )
    elif action == "dopros_snitch":
        text = (
            "👉 <b>ДОНОС СОСТАВЛЕН!</b>\n\n"
            "Анон исписал 12 страниц мелким почерком, сдав с потрохами всех щитпостеров и любителей лолей в треде!\n"
            "Товарищ майор довольно потёр руки и пожал руку сознательному гражданину:\n"
            "<i>«Родина тебя не забудет! Пативан выезжает по новым адресам!»</i>\n\n"
            "Гражданин отпущен с почётной грамотой осведомителя."
        )
    else:
        text = "Допрос окончен."

    try:
        await callback.message.edit_text(text, parse_mode="HTML")
    except Exception:
        await callback.message.answer(text, parse_mode="HTML")
    await callback.answer()

# --- ДРУЖИННИК И ШТРАФЫ ---
USER_DRUZHINA_COOLDOWN: dict[int, float] = {}
DRUZHINA_COOLDOWN_SEC: float = 86400.0

@dp.message(Command("fine", "штраф", "druzhina", "дружинник", ignore_case=True, ignore_mention=True))
async def cmd_fine(message: types.Message, board_id: str | None):
    if not board_id: return
    user_id = message.from_user.id
    now = time.time()
    db = await get_pool()

    if not message.reply_to_message:
        await message.answer("❌ Команда применяется <b>ответом (Reply)</b> на сообщение нарушителя!", parse_mode="HTML")
        return

    target_id = await get_author_id_by_reply(message)
    if not target_id and message.reply_to_message.from_user and not message.reply_to_message.from_user.is_bot:
        target_id = message.reply_to_message.from_user.id

    if not target_id or target_id == 0:
        await message.answer("❌ Не удалось определить автора поста для выписки штрафа (системное сообщение)!")
        return

    if target_id == user_id:
        await message.answer("❌ Нельзя выписать штраф самому себе, шизоид!")
        return

    active_items = await _get_user_active_items(db, user_id, board_id)
    if active_items.get("badge_druzhinnik_expires", 0) <= now:
        p_druzh = get_current_item_price("badge_druzhinnik")
        await message.answer(
            f"❌ У тебя нет активного <b>Удостоверения дружинника</b>!\n"
            f"Приобрети его в <code>/shop</code> (раздел Аптека) за {p_druzh} ₪ на 7 дней.",
            parse_mode="HTML"
        )
        return

    last_fine = USER_DRUZHINA_COOLDOWN.get(user_id, 0.0)
    if now - last_fine < DRUZHINA_COOLDOWN_SEC:
        rem_h = int((DRUZHINA_COOLDOWN_SEC - (now - last_fine)) // 3600) + 1
        await message.answer(f"⏳ Твоя дружинницкая смена окончена. Следующий рейд со штрафом доступен через {rem_h} ч.")
        return

    if is_admin(target_id, board_id):
        admin_fine = 30.0
        cur_bal = await get_user_global_balance(db, user_id)
        act_fine = min(admin_fine, max(0.0, cur_bal))
        if act_fine > 0:
            await deduct_user_global_balance(db, user_id, board_id, act_fine)
            await add_to_abu_fund(db, act_fine, donor_id=user_id, reason="Штраф дружиннику за наезд на админа")
            await record_user_transaction(db, user_id, -act_fine, "police", "Штраф за наезд на админа")
        await message.answer(
            f"🚨 <b>ПРЕВЫШЕНИЕ СЛУЖЕБНЫХ ПОЛНОМОЧИЙ!</b>\n\n"
            f"Ты попытался оштрафовать <b>Администратора</b> борды!\n"
            f"Товарищ майор лично оторвал дружиннику погоны и выписал штраф <code>-{act_fine:,.0f} ₪</code> за самоуправство!",
            parse_mode="HTML"
        )
        return

    target_items = await _get_user_active_items(db, target_id, board_id)
    if target_items.get("reflect_shield_until", 0) > now or target_items.get("shield_until", 0) > now:
        cur_bal = await get_user_global_balance(db, user_id)
        act_fine = min(15.0, max(0.0, cur_bal))
        if act_fine > 0:
            await deduct_user_global_balance(db, user_id, board_id, act_fine)
            await add_to_abu_fund(db, act_fine, donor_id=user_id, reason="Отражение штрафа щитом")
        USER_DRUZHINA_COOLDOWN[user_id] = now
        await message.answer(
            "🔰 <b>РИКОШЕТ ЗЕРКАЛЬНОГО ЩИТА!</b>\n\n"
            "У нарушителя оказался активирован Зеркальный Щит!\n"
            "Постановление о штрафе отскочило обратно в дружинника. Ты оштрафован сам на 15 ₪!",
            parse_mode="HTML"
        )
        return

    USER_DRUZHINA_COOLDOWN[user_id] = now
    fine_val = 15.0
    target_bal = await get_user_global_balance(db, target_id)
    act_target_fine = min(fine_val, max(0.0, target_bal))

    if act_target_fine > 0:
        await deduct_user_global_balance(db, target_id, board_id, act_target_fine)
        await add_to_abu_fund(db, 5.0, donor_id=target_id, reason="Доля Абу от штрафа дружинника")
        await record_user_transaction(db, target_id, -act_target_fine, "police", "Штраф от дружинника")
        druzh_reward = max(0.0, act_target_fine - 5.0)
        if druzh_reward > 0:
            await add_user_global_balance(db, user_id, board_id, druzh_reward)
            await record_user_transaction(db, user_id, druzh_reward, "police", "Премия дружинника")
    else:
        druzh_reward = 0.0

    target_anon = f"Анон [{get_anon_id(target_id)}]"
    fine_text = (
        f"🪪 <b>ШТРАФ ОТ НАРОДНОЙ ДРУЖИНЫ!</b>\n\n"
        f"Дружинник выявил нарушение общественного порядка у гражданина <b>{target_anon}</b>!\n"
        f"💸 С нарушителя взыскано: <code>-{act_target_fine:,.0f} ₪</code>\n"
        f"💰 Премия дружинника: <code>+{druzh_reward:,.0f} ₪</code> <i>(5 ₪ ушло в Фонд Абу)</i>\n"
        f"<i>(Следующий рейд со штрафом доступен через 24 часа.)</i>"
    )

    try:
        await message.bot.send_message(
            chat_id=message.chat.id,
            text=fine_text,
            reply_to_message_id=message.reply_to_message.message_id,
            parse_mode="HTML"
        )
    except Exception:
        await message.answer(fine_text, parse_mode="HTML")

    try:
        await message.bot.send_message(
            chat_id=target_id,
            text=(
                f"🪪 <b>ПОСТАНОВЛЕНИЕ О ШТРАФЕ ОТ ДРУЖИНЫ!</b>\n\n"
                f"На борде <b>/{board_id}/</b> дружинник оштрафовал вас на <code>{act_target_fine:,.0f} ₪</code> за нарушение порядка."
            ),
            parse_mode="HTML"
        )
    except Exception:
        pass

async def _process_stacked_anime_command(
    message: types.Message,
    board_id: str,
    fetcher_tasks: list[Callable[[], Awaitable[Optional[str]]]],
    caption: str,
    stream: str = 'ru',
    is_loli: bool = False
):
    """
    Универсальный обработчик для "стакающихся" аниме-команд.
    """
    working_msg = None
    gate_acquired = False
    try:
        if not await check_anime_cmd_cooldown(message, board_id):
            return
        user_id = message.from_user.id
        b_data = board_data[board_id]
        if user_id in b_data['users']['banned'] or \
           (b_data['mutes'].get(user_id) and b_data['mutes'][user_id] > datetime.now(UTC)):
            try: await message.delete()
            except TelegramBadRequest: pass
            return
        try: await message.delete()
        except TelegramBadRequest: pass
        searching_phrase = random.choice(ANIME_CMD_SEARCHING_PHRASES)
        working_msg = await message.bot.send_message(message.chat.id, searching_phrase)
        gate_wait_started = time.time()
        await anime_media_gate.acquire()
        gate_acquired = True
        gate_wait_sec = time.time() - gate_wait_started
        if gate_wait_sec > 0.05:
            runtime_logger.warning(
                "anime_media_wait %s",
                json.dumps(
                    {
                        "ts": round(time.time(), 3),
                        "board_id": board_id,
                        "user_id": user_id,
                        "wait_sec": round(gate_wait_sec, 3),
                        "concurrency": ANIME_MEDIA_CONCURRENCY,
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
            )
        print(f"[{board_id}] Шаг 1: Запускаю {len(fetcher_tasks)} задач на получение URL для user {user_id}...")
        successful_downloads = await _collect_stacked_anime_downloads(fetcher_tasks, board_id, user_id, "command")
        if not successful_downloads:
            raise ValueError("Не удалось скачать ни одного изображения.")
            
        content = _prepare_anime_content(successful_downloads, caption)

        await _publish_anime_post(message, board_id, user_id, content, stream, len(successful_downloads))
        
        # --- LOLI HOURLY RISK-REWARD EVENT ---
        if is_loli:
            spawn_task(_process_loli_reward_and_risk(message, board_id, user_id, len(successful_downloads)))

        # --- EVENT / WAIFU BONUS DROP LOGIC ---
        if random.random() < 0.15:
            is_nsfw_board = board_id in ['b', 'h', 'a']
            event_urls = await get_event_anime_images(is_nsfw=is_nsfw_board, is_loli=is_loli, count=5)
            if event_urls:
                from aiogram.types import InputMediaPhoto, InputMediaVideo
                waifu_drop_caption = (
                    "✨ <b>СЕКРЕТНЫЙ ДРОП ВАЙФУ!</b> 🌸\n"
                    "<i>Тебе выпала редкая бонусная коллекция артов (шанс 15%)!</i>"
                )
                media = []
                gif_urls = []
                for idx, u in enumerate(event_urls):
                    kind = classify_media_url(u)
                    item_caption = waifu_drop_caption if idx == 0 else None
                    if kind == 'video':
                        media.append(InputMediaVideo(media=u, caption=item_caption, parse_mode='HTML', supports_streaming=True))
                    elif kind == 'photo':
                        media.append(InputMediaPhoto(media=u, caption=item_caption, parse_mode='HTML'))
                    elif kind == 'animation':
                        gif_urls.append(u)
                if media:
                    try:
                        if len(media) == 1:
                            # Telegram API sendMediaGroup requires minimum 2 items.
                            # With 1 item, fall back to single-message dispatch.
                            item = media[0]
                            if isinstance(item, InputMediaVideo):
                                await message.bot.send_video(
                                    chat_id=message.chat.id,
                                    video=item.media,
                                    caption=waifu_drop_caption,
                                    parse_mode='HTML',
                                    supports_streaming=True
                                )
                            else:
                                await message.bot.send_photo(
                                    chat_id=message.chat.id,
                                    photo=item.media,
                                    caption=waifu_drop_caption,
                                    parse_mode='HTML'
                                )
                        else:
                            await message.bot.send_media_group(
                                chat_id=message.chat.id,
                                media=media
                            )
                    except TelegramForbiddenError:
                        runtime_logger.warning("TelegramForbiddenError sending event media group")
                    except TelegramRetryAfter as e:
                        delay = float(getattr(e, "retry_after", 5) or 5) + 1.0
                        await asyncio.sleep(delay)
                        try:
                            if len(media) == 1:
                                item = media[0]
                                if isinstance(item, InputMediaVideo):
                                    await message.bot.send_video(chat_id=message.chat.id, video=item.media, supports_streaming=True)
                                else:
                                    await message.bot.send_photo(chat_id=message.chat.id, photo=item.media)
                            else:
                                await message.bot.send_media_group(chat_id=message.chat.id, media=media)
                        except Exception as retry_err:
                            runtime_logger.error(f"Failed retry sending event media group: {retry_err}")
                    except TelegramBadRequest as e:
                        runtime_logger.warning(f"TelegramBadRequest sending event media group: {e}")
                    except Exception as e:
                        runtime_logger.error(f"Failed to send event media group: {e}", exc_info=True)
                for gif_url in gif_urls:
                    try:
                        await message.bot.send_animation(
                            chat_id=message.chat.id,
                            animation=gif_url
                        )
                    except TelegramForbiddenError:
                        runtime_logger.warning(f"TelegramForbiddenError sending event GIF animation ({gif_url})")
                    except TelegramRetryAfter as e:
                        delay = float(getattr(e, "retry_after", 5) or 5) + 1.0
                        await asyncio.sleep(delay)
                        try:
                            await message.bot.send_animation(chat_id=message.chat.id, animation=gif_url)
                        except Exception as retry_err:
                            runtime_logger.error(f"Failed retry sending GIF animation ({gif_url}): {retry_err}")
                    except TelegramBadRequest as e:
                        runtime_logger.warning(f"TelegramBadRequest sending event GIF animation ({gif_url}): {e}")
                    except Exception as e:
                        runtime_logger.error(f"Failed to send event GIF animation ({gif_url}): {e}")
    except ValueError as e:
        print(f"[{board_id}] Не удалось обработать команду для user {user_id}: {e}")
        fail_text = "Не удалось получить контент. API недоступны или лимит исчерпан."
        error_msg = await message.bot.send_message(message.chat.id, fail_text)
        spawn_task(delete_message_after_delay(error_msg, 10))
    finally:
        if gate_acquired:
            anime_media_gate.release()
        if working_msg:
            try: await working_msg.delete()
            except TelegramBadRequest: pass

@dp.message(Command("del", "delete", "rm", "удалить"))
async def cmd_del(message: types.Message, board_id: str | None, stream: str = 'ru'):
    if not board_id: return
    user_id = message.from_user.id
    target_msg = message.reply_to_message
    lang = stream if ENABLE_MULTILANG else ('en' if board_id == 'int' else 'ru')

    if not target_msg:
        msg = "Reply to a message to delete: <code>/del</code>" if lang == 'en' else "⚠️ Ответьте на сообщение, которое хотите удалить: <code>/del</code>"
        try:
            sent = await message.answer(msg, parse_mode="HTML")
            spawn_task(delete_message_after_delay(sent, 5))
            await message.delete()
        except Exception:
            pass
        return

    admin_status = is_admin(user_id, board_id)

    # 1. Запрет дворников на /sex/
    if board_id == "sex" and not admin_status:
        await message.answer("🚮 <b>В этом разделе дворники не работают!</b>\nЗдесь постят контент, а не мусор. Иди подметай в /b/ или /trash/.", parse_mode="HTML")
        try: await message.delete()
        except Exception: pass
        return

    db = await get_pool()
    is_janitor = False
    janitor_deletes_left = 0
    active_items = {}

    if not admin_status:
        async with db_lock:
            active_items = await _get_user_active_items(db, user_id, board_id)
            janitor_until = active_items.get("janitor_until", 0)
            janitor_deletes_left = active_items.get("janitor_deletes_left", 0)
            if janitor_until > time.time() and janitor_deletes_left > 0:
                is_janitor = True

    if not admin_status and not is_janitor:
        try: await message.delete()
        except Exception: pass
        return

    key = (target_msg.chat.id, target_msg.message_id)
    post_num = message_to_post.get(key)
    if not post_num:
        info = await get_post_info_by_copy(target_msg.chat.id, target_msg.message_id)
        if info: post_num = info[0]

    # 2. Проверка возраста поста и защиты фольгой (только для обычных дворников)
    if is_janitor and not admin_status:
        post_author_id = 0
        post_ts = 0
        if post_num:
            async with storage_lock:
                if post_num in messages_storage:
                    p_data = messages_storage[post_num]
                    post_author_id = p_data.get('author_id', 0)
                    post_ts = p_data.get('timestamp', 0)
            if not post_ts or not post_author_id:
                async with db.execute("SELECT author_id, timestamp FROM Posts WHERE post_num = ?", (post_num,)) as cur:
                    p_row = await cur.fetchone()
                    if p_row:
                        post_author_id = p_row[0]
                        post_ts = p_row[1]

        post_ts_float = 0.0
        if post_ts:
            if isinstance(post_ts, (int, float)):
                post_ts_float = float(post_ts)
            elif isinstance(post_ts, datetime):
                post_ts_float = post_ts.timestamp()
            elif isinstance(post_ts, str):
                try:
                    post_ts_float = float(post_ts)
                except ValueError:
                    try:
                        from datetime import datetime as dt_cls
                        post_ts_float = dt_cls.fromisoformat(post_ts.replace("Z", "+00:00")).timestamp()
                    except Exception:
                        post_ts_float = 0.0

        now = time.time()
        # Ограничение возраста: максимум 15 минут (900 сек)
        if post_ts_float > 0 and (now - post_ts_float > 900):
            await message.answer("⏱️ <b>Слишком старый пост!</b>\nДворники могут убирать только свежий мусор (не старше 15 минут). Старые посты трогать запрещено!\n<i>(Счётчик удалений сохранён)</i>", parse_mode="HTML")
            try: await message.delete()
            except Exception: pass
            return

        # Защита фольгой
        if post_author_id:
            target_items = await _get_user_active_items(db, post_author_id, board_id)
            if target_items.get("tinfoil_hat", 0) > now:
                destroyed, left_h, left_m, _ = apply_tinfoil_damage(target_items, int(now), hours_damage=4.0, burn_chance=0.15)
                async with db_lock:
                    await db.execute("UPDATE Users SET active_items = ? WHERE user_id = ? AND board_id = ?",
                                     (json.dumps(target_items), post_author_id, board_id))
                    await db.commit()
                await message.answer("👽 <b>ШАПОЧКА ИЗ ФОЛЬГИ!</b>\nУ автора поста надета Шапочка из фольги! Метла дворника соскользнула, пост защищён от удаления.", parse_mode="HTML")
                try: await message.delete()
                except Exception: pass
                return

        # Списываем 1 попытку только при успешном удалении
        async with db_lock:
            janitor_deletes_left -= 1
            active_items["janitor_deletes_left"] = janitor_deletes_left
            await db.execute(
                "UPDATE Users SET active_items = ? WHERE user_id = ? AND board_id = ?",
                (json.dumps(active_items), user_id, board_id)
            )
            await db.commit()

    # 3. Выполнение удаления
    deleted_count = 0
    if post_num:
        deleted_count = await delete_single_post(post_num, message.bot)
        role_str = "Админ" if admin_status else "Дворник"
        await log_global_event('bot', f"🗑️ DEL: {role_str} {user_id} удалил пост #{post_num} на /{board_id}/ (и {deleted_count} копий)")
        
        ach_janitor_note = ""
        if is_janitor and deleted_count > 0:
            from achievements_engine import check_and_unlock_achievement
            unlocked, ach_info = check_and_unlock_achievement(active_items, "ach_janitor_clean")
            if unlocked and ach_info:
                await add_user_global_balance(db, user_id, board_id, ach_info["reward_cash"])
                async with db_lock:
                    await db.execute("UPDATE Users SET active_items = ? WHERE user_id = ? AND board_id = ?", (json.dumps(active_items), user_id, board_id))
                    await db.commit()
                ach_janitor_note = f"\n\n🏆 <b>ДОСТИЖЕНИЕ:</b> {ach_info['name']} (+{ach_info['reward_cash']} ₪)!"

        if lang == 'en':
            resp = f"🗑 Post #{post_num} deleted ({deleted_count} copies)."
            if is_janitor:
                resp += f" 🚮 Janitor: {janitor_deletes_left} deletes remaining."
        elif lang == 'jp':
            resp = f"🗑 投稿 #{post_num} とコピー ({deleted_count}件) を削除しました。"
            if is_janitor:
                resp += f" 🚮 掃除員チケット: 残り {janitor_deletes_left} 回。"
        else:
            resp = f"🗑 Пост №{post_num} и копии ({deleted_count}) удалены."
            if is_janitor:
                resp += f" 🚮 Удалено как Дворник (по Билету). Осталось: {janitor_deletes_left} удалений."
        resp += ach_janitor_note
        await message.answer(resp)
    else:
        try:
            await target_msg.delete()
            await message.answer("🗑 Сообщение удалено.")
        except Exception:
            await message.answer("⚠️ Не удалось найти пост в базе (возможно, он уже удален).")

    try: await message.delete()
    except Exception: pass

async def _safe_delete_user_message(message: types.Message):
    try:
        if (datetime.now(UTC) - message.date).total_seconds() < 48 * 3600:
            await message.delete()
    except TelegramBadRequest:
        pass

@dp.message(Command("deanon"))
async def cmd_deanon(message: Message, board_id: str | None, stream: str = 'ru'):
    if not board_id: return
    current_time = time.time()
    # storage_lock убран: кулдаун в board_data, исключение даёт deanon_lock.
    async with deanon_lock:
        b_data = board_data[board_id]
        on_cooldown = current_time - b_data.get('last_deanon_time', 0) < DEANON_COOLDOWN
        if not on_cooldown:
            b_data['last_deanon_time'] = current_time
    if on_cooldown:
        cooldown_msg = random.choice(DEANON_COOLDOWN_PHRASES)
        try:
            sent_msg = await message.answer(cooldown_msg)
            spawn_task(delete_message_after_delay(sent_msg, 5))
        except Exception: pass
        await _safe_delete_user_message(message)
        return
    lang = 'en' if board_id == 'int' else 'ru'
    if not message.reply_to_message:
        reply_text = "👀 Reply to a message to de-anonymize!" if lang == 'en' else "⚠️ Ответьте на анонимное сообщение юзера, чтобы попытаться узнать автора: <code>/deanon</code>"
        await message.answer(reply_text, parse_mode="HTML")
        await _safe_delete_user_message(message)
        return
    user_id = message.from_user.id
    b_data = board_data[board_id] # Переопределение b_data для ясности
    user_location = 'main'
    if board_id in THREAD_BOARDS:
        user_location = b_data.get('user_state', {}).get(user_id, {}).get('location', 'main')
    original_author_id = None
    target_post = None
    original_author_id = await get_author_id_by_reply(message)
    async with storage_lock:
        target_chat_id = message.reply_to_message.chat.id
        target_mid = message.reply_to_message.message_id
        target_post = message_to_post.get((target_chat_id, target_mid))
    if not original_author_id:
        reply_text = "🚫 Could not find the post to de-anonymize..." if lang == 'en' else "🚫 Не удалось найти пост для деанона..."
        await message.answer(reply_text)
        await _safe_delete_user_message(message)
        return
    if original_author_id == 0:
        reply_text = "⚠️ System messages cannot be de-anonymized." if lang == 'en' else "⚠️ Системные сообщения нельзя деанонить."
        await message.answer(reply_text)
        await _safe_delete_user_message(message)
        return
    deanon_text = generate_deanon_info(lang=lang)
    header_text_prefix = "### DEANON ###" if lang == 'en' else "### ДЕАНОН ###"
    now_dt = datetime.now(UTC)
    async def create_and_send_deanon_post(thread_id_override=None):
        content = {"type": "text", "text": deanon_text, "reply_to_post": target_post, "is_system_message": True}
        pnum = await create_post(
            board_id=board_id,
            author_id=0,
            content=content,
            timestamp=now_dt.timestamp(),
            is_from_site=False, stream=stream,
            thread_id_from_bot=thread_id_override
        )
        if not pnum:
            print(f"⛔ [{board_id}] КРИТИЧЕСКАЯ ОШИБКА: не удалось создать пост в БД для /deanon.")
            return
        header_text = await format_header(board_id, pnum)
        content['header'] = f"{header_text_prefix}\n{header_text}"
        content['post_num'] = pnum
        await update_post_content(pnum, content)
        async with storage_lock:
            messages_storage[pnum] = {'author_id': 0, 'timestamp': now_dt, 'content': content, 'board_id': board_id, 'thread_id': thread_id_override}
            if thread_id_override:
                thread_info = get_thread_info(board_id, thread_id_override)
                if thread_info:
                    thread_info['last_activity_at'] = time.time()
        recipients = None
        if thread_id_override:
            thread_info = get_thread_info(board_id, thread_id_override)
            if thread_info:
                recipients = thread_info.get('subscribers', set())
        else:
            recipients = b_data.get('users', {}).get('active', set())
        if recipients:
            await enqueue_board_message(board_id, {
                "recipients": recipients, "content": content, "post_num": pnum,
                "board_id": board_id, "thread_id": thread_id_override
            })
    if board_id in THREAD_BOARDS and user_location != 'main':
        thread_id = user_location
        thread_info = get_thread_info(board_id, thread_id)
        if thread_info and not thread_info.get('is_archived'):
            await create_and_send_deanon_post(thread_id_override=thread_id)
        else: # Если тред не найден, постим на главную
             await create_and_send_deanon_post()
    else:
        await create_and_send_deanon_post()
    await _safe_delete_user_message(message)
