# --- Fallback router: MUST be included LAST so all sub-routers get a chance first ---
from aiogram import Router as _Router
_fallback_router = _Router(name="fallback_unknown_cmd")

@_fallback_router.message(F.text.regexp(r"^/\w+(@\w+)?\b"))
async def handle_unknown_command_spam(message: types.Message):
    """
    Отлавливает все неопознанные команды и применяет к ним анти-спам политику.
    ВАЖНО: этот хэндлер теперь в отдельном router (а не на dp напрямую),
    чтобы sub-routers (stats_hub_router, economy_router и др.) имели приоритет.
    """
    user_id = message.from_user.id
    current_time = time.time()
    unknown_command_tracker[user_id] = [t for t in unknown_command_tracker[user_id] if current_time - t < 4]
    if unknown_command_tracker[user_id] and isinstance(unknown_command_tracker[user_id][-1], float):
        if current_time < unknown_command_tracker[user_id][-1]:
            try:
                await message.delete()
            except TelegramBadRequest:
                pass
            return
    unknown_command_tracker[user_id].append(current_time)
    command_timestamps = [t for t in unknown_command_tracker[user_id] if isinstance(t, (int, float))]
    if len(command_timestamps) > 2:
        ban_until = current_time + 20
        unknown_command_tracker[user_id] = [ban_until]
        try:
            user_lang_code = message.from_user.language_code or 'en'
            if 'ja' in user_lang_code:
                msg = "コマンドを送信しすぎです。20秒お待ちください。"
            elif 'ru' in user_lang_code or 'uk' in user_lang_code or 'be' in user_lang_code:
                msg = "Слишком много неизвестных команд. Подождите 20 секунд."
            else:
                msg = "Too many unknown commands. Wait 20 seconds."
            await message.answer(msg, disable_notification=True)
        except (TelegramForbiddenError, TelegramBadRequest):
            pass
    try:
        await message.delete()
    except TelegramBadRequest:
        pass

dp.include_router(_fallback_router)  # LAST — catches unhandled /commands AFTER all other routers

async def main():

    lock_file = "bot.lock"
    current_pid = os.getpid()
    if os.path.exists(lock_file):
        old_pid = None
        try:
            for _ in range(3):
                try:
                    lock_text = await asyncio.to_thread(_read_text_file_stripped, lock_file)
                    old_pid = int(lock_text)
                    break
                except (IOError, ValueError):
                    await asyncio.sleep(0.2)
            if old_pid is None:
                print("⚠️ Lock-файл нечитаемый после повторов. Удаляю как stale и продолжаю.")
                os.remove(lock_file)
            elif old_pid != current_pid:
                is_real_bot = False
                try:
                    p = psutil.Process(old_pid)
                    cmd = " ".join(p.cmdline()).lower()
                    if "python" in p.name().lower() and "main.py" in cmd:
                        is_real_bot = True
                except Exception:
                    is_real_bot = False

                if is_real_bot:
                    print(f"⛔ Бот с PID {old_pid} уже запущен! Завершение работы...")
                    sys.exit(1)
                else:
                    print(f"⚠️ Lock-файл содержал старый/переиспользованный PID {old_pid}. Очищаю lock.")
                    os.remove(lock_file)
        except (IOError, ValueError):
            print("⚠️ Lock-файл поврежден. Удаляю и продолжаю.")
            try: os.remove(lock_file)
            except Exception: pass
    tmp_lock_file = f"{lock_file}.{current_pid}.tmp"
    await asyncio.to_thread(_write_text_file_atomic, lock_file, str(current_pid), tmp_lock_file)
    session = None
    healthcheck_site = None
    global GLOBAL_BOTS
    background_tasks = []  # Храним задачи здесь
    try:
        loop = asyncio.get_running_loop()
        loop.set_default_executor(ThreadPoolExecutor(max_workers=DEFAULT_EXECUTOR_WORKERS, thread_name_prefix="bot-default"))
        await warm_executor_pool(loop, None, DEFAULT_EXECUTOR_WORKERS, "default")
        await warm_executor_pool(loop, save_executor, 2, "save")
        await warm_executor_pool(loop, git_executor, 1, "git")
        warm_native_media_stack()
        await initialize_database()
        await create_pool()
        await sync_boards_with_config()
        await load_state()
        load_graph_stats() 
        global ROULETTE_EVENTS
        ROULETTE_EVENTS = load_roulette_data("roulette_data.json")
        if ROULETTE_EVENTS:
            print(f"✅ Данные рулетки успешно загружены. Всего событий: {len(ROULETTE_EVENTS)}")
        else:
            print("⚠️ Не удалось загрузить данные для рулетки.")
        GLOBAL_BOTS, session = await initialize_bots()
        if not GLOBAL_BOTS:
            print("❌ Не найдено ни одного токена бота. Завершение работы.")
            return
        shared_state.GLOBAL_BOTS.clear()
        shared_state.GLOBAL_BOTS.update(GLOBAL_BOTS)
        active_bots_list = list(GLOBAL_BOTS.values())
        print(f"✅ Инициализировано {len(active_bots_list)} ботов.")
        await setup_pinned_messages(GLOBAL_BOTS)
        try:
            healthcheck_site = await start_healthcheck()
        except Exception as e:
            print(f"⛔ Не удалось запустить healthcheck сервер: {e}")
            healthcheck_site = None
        setup_lifecycle_handlers(loop, active_bots_list, healthcheck_site)
        await restore_durable_delivery_queue()
        try:
            import drop_engine
            db_conn = await get_pool()
            loaded_drops = await drop_engine.init_drop_engine(db_conn)
            if loaded_drops > 0:
                print(f"💸 [DropEngine] Восстановлено {loaded_drops} активных дропов шекелей.")
        except Exception as e:
            print(f"⚠️ Ошибка инициализации DropEngine: {e}")
        background_tasks = await start_background_tasks(GLOBAL_BOTS, healthcheck_site)
        print("⏳ Даем 1.5 секунд на инициализацию...")
        await asyncio.sleep(1.5)
        print("🚀 Запускаем polling...")
        await setup_bot_commands(GLOBAL_BOTS)
        await dp.start_polling(
            *active_bots_list, skip_updates=False,
            allowed_updates=dp.resolve_used_update_types(),
            reset_webhook=True, timeout=60
        )
    except Exception as e:
        import traceback
        print(f"🔥 Критическая ошибка в main: {e}\n{traceback.format_exc()}")
    finally:
        if drain_shutdown_requested:
            await wait_for_delivery_queues_to_drain(
                CONTROLLED_STOP_DRAIN_TIMEOUT_SEC,
                CONTROLLED_STOP_LOG_INTERVAL_SEC,
            )
        print("🛑 Остановка фоновых задач...")
        for task in background_tasks:
            task.cancel()
        if background_tasks:
            await asyncio.gather(*background_tasks, return_exceptions=True)
        if not is_shutting_down:
            bots_to_close = []
            if 'active_bots_list' in locals() and active_bots_list:
                bots_to_close = active_bots_list
            elif GLOBAL_BOTS:
                bots_to_close = list(GLOBAL_BOTS.values())
            await graceful_shutdown(bots_to_close, healthcheck_site)
        try:
            await close_pool()
        except Exception as e:
            print(f"⚠️ Ошибка при close_pool в main: {e}")
        if session:
            try:
                await session.close()
                print("✅ Общая HTTP сессия закрыта.")
            except Exception:
                pass
            if hasattr(session, '_connector') and session._connector and not session._connector.closed:
                await session._connector.close()
                print("✅ Коннектор закрыт.")
        if os.path.exists(lock_file):
            try:
                pid_in_file = int(await asyncio.to_thread(_read_text_file_stripped, lock_file))
                if pid_in_file == current_pid: os.remove(lock_file)
            except (IOError, ValueError):
                print("⚠️ Lock-файл нечитаемый при shutdown; не удаляю чужой возможный live-lock.")

async def schedule_persona_reply(bot, board_id: str, target_post_num: int, context_text: str, stream: str, is_admin_trigger: bool = False, photo_file_id: str = None, is_dialogue: bool = False):
    try:
        from site_tgach.persona_bot import generate_anon_reply, is_valid_for_persona

        if target_post_num and target_post_num in _persona_processed_posts:
            print(f"ℹ️ [Persona Debounce] Reply for post #{target_post_num} already processed, skipping duplicate trigger.")
            return
        if target_post_num:
            _persona_processed_posts.add(target_post_num)
            if len(_persona_processed_posts) > 3000:
                _persona_processed_posts.clear()

        now_ts = time.time()

        attach_file_id = None
        attach_media_type = None

        if not photo_file_id and target_post_num and target_post_num in messages_storage:
            p_data = messages_storage[target_post_num]
            c = p_data.get('content', {})
            m_type = c.get('type')
            if m_type == 'image': m_type = 'photo'
            if m_type in {'photo', 'video', 'animation', 'gif', 'video_note', 'sticker', 'document'}:
                photo_file_id = c.get('thumbnail_file_id') or c.get('file_id')
                attach_file_id = c.get('file_id')
                attach_media_type = m_type
            elif m_type == 'media_group' and c.get('media'):
                for m in c.get('media', []):
                    if m.get('file_id'):
                        photo_file_id = m.get('thumbnail_file_id') or m.get('file_id')
                        attach_file_id = m.get('file_id')
                        sub_type = m.get('type') or 'photo'
                        attach_media_type = 'photo' if sub_type == 'image' else sub_type
                        break
            # Если в самом посте нет картинки, проверим родительский пост, на который отвечают
            if not photo_file_id:
                reply_to_num = p_data.get('reply_to_post_num') or p_data.get('reply_to')
                if reply_to_num and reply_to_num in messages_storage:
                    parent_c = messages_storage[reply_to_num].get('content', {})
                    pm_type = parent_c.get('type')
                    if pm_type == 'image': pm_type = 'photo'
                    if pm_type in {'photo', 'video', 'animation', 'gif', 'video_note', 'sticker', 'document'}:
                        photo_file_id = parent_c.get('thumbnail_file_id') or parent_c.get('file_id')
                        attach_file_id = parent_c.get('file_id')
                        attach_media_type = pm_type
                    elif pm_type == 'media_group' and parent_c.get('media'):
                        for m in parent_c.get('media', []):
                            if m.get('file_id'):
                                photo_file_id = m.get('thumbnail_file_id') or m.get('file_id')
                                attach_file_id = m.get('file_id')
                                sub_type = m.get('type') or 'photo'
                                attach_media_type = 'photo' if sub_type == 'image' else sub_type
                                break

        vision_desc = None
        if photo_file_id and not (context_text and "[ИЗОБРАЖЕНИЕ:" in context_text):
            vision_desc = await analyze_telegram_photo(bot, photo_file_id, caption=context_text)
            if vision_desc:
                img_tag = f"\n[ИЗОБРАЖЕНИЕ: {vision_desc}]"
                context_text = (context_text or "") + img_tag

        if not is_admin_trigger and not is_valid_for_persona(context_text):
            return
            
        await asyncio.sleep(random.uniform(12.0, 35.0) if not is_admin_trigger else 0)
        
        print(f"🤖 [Persona] Requesting reply generation for post {target_post_num} on {board_id} (is_dialogue={is_dialogue})...")
        
        # Строим общую атмосферу доски (25 последних постов)
        atmosphere_context = await build_board_atmosphere_context(board_id, exclude_post_num=target_post_num, limit=25)
        
        # Строим контекст всей цепочки ответов (до 25 уровней)
        chain_context = await build_reply_chain_context(target_post_num, max_depth=25)
        if not chain_context:
            chain_context = context_text
        elif photo_file_id and vision_desc and "[ИЗОБРАЖЕНИЕ:" not in chain_context:
            chain_context += f"\n[ИЗОБРАЖЕНИЕ: {vision_desc}]"

        replies = await generate_anon_reply(
            context_text=chain_context,
            target_post=context_text,
            is_dialogue=is_dialogue,
            atmosphere_text=atmosphere_context
        )
        
        # Гарантия от "замалчивания": если юзер вел диалог с ботом, но генератор сбросился — даем аноновский фаллбэк-ответ
        if not replies and is_dialogue:
            print(f"⚠️ [Persona] Dialogue fallback for post {target_post_num} (preventing silence).")
            fallback_options = [
                "Понял тебя, анон.",
                "Ладно, проехали.",
                "Хз даже чё сказать на это, анон.",
                "Ну допустим.",
                "Ладно, забей.",
                "Останемся при своих, анон."
            ]
            replies = [random.choice(fallback_options)]

        if not replies:
            print(f"⚠️ [Persona] Generation failed or returned empty for post {target_post_num}.")
            return
            
        print(f"✅ [Persona] Successfully generated {len(replies)} replies for post {target_post_num}.")
            
        for i, text in enumerate(replies):
            now_dt = datetime.now(UTC)
            # Прикрепляем картинку только в 30% случаев чтобы не спамить медиа
            attach_media = attach_file_id and attach_media_type in {'photo', 'video', 'animation', 'gif'} and i == 0 and random.random() < 0.30
            content = {
                'type': attach_media_type if attach_media else 'text',
                'is_system_message': True,
                'archive_allowed': True
            }
            if attach_media:
                content['caption'] = text
                content['file_id'] = attach_file_id
            else:
                content['text'] = text
                
            pnum = await create_post(
                board_id=board_id,
                author_id=0,
                content=content,
                timestamp=now_dt.timestamp(),
                is_from_site=False, stream=stream,
                reply_to=target_post_num if target_post_num else None
            )
            if pnum:
                header = await format_header(board_id, pnum, 0)
                content['header'] = f"### АНОН ###\n{header}" if stream == 'ru' else f"### ANON ###\n{header}"
                await update_post_content(pnum, content)
                async with storage_lock:
                    messages_storage[pnum] = {
                        'author_id': 0, 'timestamp': now_dt, 
                        'content': content, 'board_id': board_id,
                        'reply_to_post_num': target_post_num if target_post_num else None
                    }
                await process_new_post(NewPostParams(
                    bot_instance=bot,
                    board_id=board_id,
                    user_id=0,
                    content=content,
                    reply_to_post=target_post_num if target_post_num else None,
                    is_shadow_muted=False,
                    stream=stream
                ))
            if len(replies) > 1:
                await asyncio.sleep(random.uniform(1.0, 3.0))
    except Exception as e:
        print(f"Error in schedule_persona_reply: {e}")

async def check_and_send_contextual_reply(bot: Bot, user_id: int, text: str, board_id: str, stream: str = 'ru'):
    """
    Проверяет текст на наличие паттернов и отправляет автору личное сообщение.
    Выбирает язык ответов на основе stream.
    """
    if not text or not isinstance(text, str):
        return
    lang = stream if ENABLE_MULTILANG else ('en' if board_id == 'int' else 'ru')
    if lang == 'en':
        replies_dict = CONTEXTUAL_REPLIES_EN
    elif lang == 'jp':
        replies_dict = CONTEXTUAL_REPLIES_JP
    else:
        replies_dict = CONTEXTUAL_REPLIES
    try:
        for pattern, replies in replies_dict.items():
            is_match = False
            if isinstance(pattern, str):
                if re.search(pattern, text, re.IGNORECASE):
                    is_match = True
            elif hasattr(pattern, 'search'):
                if pattern.search(text):
                    is_match = True
            if is_match:
                allowed, reason = _contextual_reply_allowed(user_id, board_id)
                if not allowed:
                    if reason:
                        runtime_logger.info(
                            "contextual_reply_skip %s",
                            json.dumps(
                                {
                                    "ts": round(time.time(), 3),
                                    "board_id": board_id,
                                    "user_id": user_id,
                                    "reason": reason,
                                },
                                ensure_ascii=False,
                                separators=(",", ":"),
                            ),
                        )
                    return
                response_text = random.choice(replies)
                try:
                    await bot.send_message(user_id, response_text, parse_mode="HTML")
                except (TelegramForbiddenError, TelegramBadRequest) as e:
                    contextual_reply_stats["send_errors"] += 1
                    print(f"ℹ️ Не удалось отправить контекстный ответ user {user_id}: {e}")
                return
    except Exception as e:
        print(f"⛔ Ошибка в check_and_send_contextual_reply для user {user_id}: {e}")

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("ℹ️ Завершение работы по запросу...")
    except SystemExit as exc:
        # SystemExit ловили вместе с KeyboardInterrupt и молча гасили, поэтому
        # процесс ВСЕГДА завершался кодом 0 - даже когда main() звал
        # sys.exit(1). А зовёт он его на двух фатальных путях: незаполненная
        # БД (load_state) и «бот с таким PID уже запущен». Супервизору оба
        # выглядели как успешный штатный выход: systemd с Restart=on-failure
        # не перезапустил бы бота, а деплой счёл бы запуск удавшимся.
        # Штатную остановку (код 0 или None) по-прежнему гасим тихо.
        if exc.code:
            print(f"⛔ Аварийное завершение, код выхода {exc.code}.")
            raise
        print("ℹ️ Завершение работы по запросу...")
